seed jsonb := $seed${"version":4,"lessons":[{"title":"บทที่ 1: ความรู้พื้นฐานเกี่ยวกับปัญญาประดิษฐ์","short":"พื้นฐาน AI","mission":{"name":"หน่วยที่ 1: ความรู้พื้นฐานเกี่ยวกับปัญญาประดิษฐ์","role":"ต้น มีนา ครูพริม และน้องเอไอ","goal":"แยกประเภท AI เข้าใจหลักการสร้างคำตอบ และรู้ข้อจำกัดของ AI ก่อนนำผลลัพธ์ไปใช้"},"simulation":{"place":"ห้องเรียนของครูพริม","context":"คาบแรกวันจันทร์ ครูพริมเขียนบนกระดานว่า “เปิดโทรศัพท์ แล้วเขียนชื่อฟีเจอร์ที่คิดว่าเป็น AI มา 5 อย่าง” ต้นเขียน ฟิลเตอร์แต่งหน้าในแอปวิดีโอสั้น ปุ่มลบคนออกจากรูปในแกลเลอรี คำบรรยายใต้คลิปที่ขึ้นเองอัตโนมัติ น้องเอไอที่เขาใช้ทำการบ้าน และเครื่องคิดเลข มีนาแย้งว่าเครื่องคิดเลขไม่น่าใช่ ต้นเถียงว่า “ก็มันคิดเลขให้เราไง” มีนาจึงกดเครื่องคิดเลข 7 คูณ 8 สามครั้ง ได้ 56 ทุกครั้งไม่ผิดเพี้ยน แล้วพิมพ์ถามน้องเอไอว่า “ขอชื่อโครงงานวิทยาศาสตร์ 3 ชื่อ” สามครั้งด้วยข้อความเดิม ได้ชื่อไม่ซ้ำกันเลยสักครั้ง ครูพริมจึงขีดกระดานเป็นสามช่อง คือ โปรแกรมทั่วไป AI เฉพาะทาง และ AI ที่สร้างของใหม่ แล้วให้ทั้งห้องช่วยกันย้ายรายชื่อลงช่อง","task":"แยกประเภท AI เข้าใจหลักการสร้างคำตอบ และรู้ข้อจำกัดของ AI ก่อนนำผลลัพธ์ไปใช้"},"videoDesc":"คลิปสั้น: “AI คืออะไรและทำงานอย่างไร?” — รู้จัก AI แบบแคบ Generative AI ความแตกต่างจากเครื่องมือค้นหา และข้อจำกัดของ AI","slides":[{"emoji":"🤖","image":"./lesson1-ai-what-is-ai.png","imageAlt":"AI คือระบบที่เรียนรู้รูปแบบจากข้อมูล","title":"AI คืออะไร?","text":"AI คือเทคโนโลยีที่ช่วยให้คอมพิวเตอร์เรียนรู้รูปแบบจากข้อมูล แล้ววิเคราะห์ คาดการณ์ หรือช่วยสร้างผลลัพธ์ในงานเฉพาะด้าน เช่น ระบบแนะนำวิดีโอ การแปลภาษา และแชตบอต AI ที่ใช้รอบตัวส่วนใหญ่เป็น AI แบบแคบ ไม่ได้คิดหรือรู้สึกเหมือนมนุษย์ทุกด้าน"},{"emoji":"✨","title":"Generative AI ทำงานอย่างไร?","text":"Generative AI เรียนรู้รูปแบบจากข้อมูลจำนวนมาก แล้วคาดการณ์คำ ภาพ เสียง หรือวิดีโอชิ้นถัดไปเพื่อสร้างผลลัพธ์ใหม่ จึงช่วยร่าง สรุป หรือเสนอไอเดียได้ดี แต่ไม่ได้ “รู้ความจริง” หรือเข้าใจประสบการณ์เหมือนมนุษย์"},{"emoji":"🔎","title":"AI ต่างจากเครื่องมือค้นหาอย่างไร?","text":"เครื่องมือค้นหาช่วยพาเราไปยังแหล่งข้อมูลและเว็บไซต์ ส่วน Generative AI ช่วยเรียบเรียงหรือสร้างคำตอบจากรูปแบบที่เรียนรู้มา เมื่อต้องใช้ข้อเท็จจริง นักเรียนควรเปิดแหล่งต้นฉบับจากการค้นหาและตรวจข้อมูล ไม่เชื่อคำตอบที่สร้างขึ้นทันที"},{"emoji":"⚠️","image":"./lesson1-ai-types.png","imageAlt":"AI มีความสามารถและข้อจำกัดต่างกัน","title":"AI มีข้อจำกัดอะไรบ้าง?","text":"AI อาจตอบผิด แต่งข้อมูล อคติ หรือไม่เข้าใจบริบทของเราได้ แม้คำตอบจะฟังดูมั่นใจและละเอียด ดังนั้นใช้ AI เพื่อช่วยคิดได้ แต่ต้องตรวจหลักฐานและให้มนุษย์รับผิดชอบการตัดสินใจเสมอ"}],"quiz":[{"id":"1.1.1","q":"ผลการทดลองของมีนา คือเครื่องคิดเลขได้ 56 ทุกครั้ง ส่วนน้องเอไอตอบไม่ซ้ำกันเลย สนับสนุนข้อสรุปใดได้ดีที่สุด","choices":["ระบบหนึ่งทำตามกฎตายตัว อีกระบบสร้างผลใหม่ทุกครั้ง จึงคนละประเภท","AI ทุกชนิดต้องตอบไม่ซ้ำกัน","เครื่องคิดเลขเรียนรู้จากคำตอบก่อนหน้า","ผลลัพธ์ต่างกันแปลว่าระบบเสีย"],"answer":0,"explain":"การทดลองนี้เปรียบเทียบความคงที่ของผลลัพธ์ ซึ่งสะท้อนวิธีทำงานเบื้องหลัง","hint":"ลองถามตัวเองว่า ถ้าไม่มีข้อมูลตัวอย่างให้เรียนรู้ โปรแกรมนี้ยังทำงานได้หรือไม่ และผลลัพธ์ที่ได้เป็นการเลือกจากของที่มีอยู่แล้ว หรือเป็นของใหม่ที่เพิ่งถูกสร้างขึ้น"},{"id":"1.1.2","q":"เกณฑ์ใดใช้แยกแอปแนะนำเพลงอัตโนมัติ ออกจากแอปที่สร้างมิวสิกวิดีโอใหม่ ได้ตรงที่สุด","choices":["ความเร็วของแอป","จำนวนผู้ใช้งาน","ผลลัพธ์เป็นการเลือกของเดิม หรือเป็นของใหม่ที่เพิ่งสร้าง","การเชื่อมต่ออินเทอร์เน็ต"],"answer":2,"explain":"ความเร็ว ความนิยม และการเชื่อมอินเทอร์เน็ต เป็นคุณสมบัติของบริการ ไม่ใช่เกณฑ์จำแนกประเภทของ AI","hint":"ลองถามตัวเองว่า ถ้าไม่มีข้อมูลตัวอย่างให้เรียนรู้ โปรแกรมนี้ยังทำงานได้หรือไม่ และผลลัพธ์ที่ได้เป็นการเลือกจากของที่มีอยู่แล้ว หรือเป็นของใหม่ที่เพิ่งถูกสร้างขึ้น"},{"id":"1.2.1","q":"ผลการเติมคำทั้งห้าครั้งสนับสนุนข้อสรุปใดเกี่ยวกับการเลือกคำของ AI ได้ดีที่สุด","choices":["ยืนยันได้ว่า AI เข้าใจเหมือนมนุษย์","พิสูจน์ว่า AI ไม่มีการสุ่มเลย","คำที่ได้สอดคล้องกับบริบท จึงสนับสนุนการเลือกคำแบบถ่วงน้ำหนัก แต่การทดลองเพียง 5 ครั้งยังพิสูจน์ไม่ได้เด็ดขาด","ทุกคำมีโอกาสเท่ากันเสมอ"],"answer":2,"explain":"แบบจำลองให้น้ำหนักคำตามบริบท การไม่พบคำหนึ่งในตัวอย่างขนาดเล็กไม่ได้หักล้างการสุ่มอย่างเด็ดขาด","hint":"ลองแยกให้ออกว่าคำตอบทั้งสามครั้ง “ต่างกันที่สำนวนภาษา” หรือ “ต่างกันที่ข้อเท็จจริง” แล้วคิดต่อว่าอะไรคือสิ่งที่ระบบทำได้ดี กับอะไรคือสิ่งที่ระบบไม่ได้รับประกัน"},{"id":"1.2.2","q":"ถ้าให้น้องเอไอเติมประโยค “ประธานชมรมถ่ายภาพคนแรกของโรงเรียนชื่อ” ซึ่งไม่เคยมีใครบันทึกไว้ที่ใด ผลน่าจะเป็นอย่างไร","choices":["อาจเติมชื่อที่ฟังดูเข้าที่ ทั้งที่ไม่มีข้อมูลรองรับ","ต้องตอบถูกเพราะประโยคชัดเจน","จะค้นทะเบียนโรงเรียนให้อัตโนมัติเสมอ","รับประกันว่าจะไม่เติมชื่อใด ๆ"],"answer":0,"explain":"การสร้างข้อความไม่ได้รับประกันการตรวจข้อเท็จจริง ระบบอาจแต่งชื่อหรือแจ้งว่าไม่มีข้อมูลก็ได้","hint":"ลองแยกให้ออกว่าคำตอบทั้งสามครั้ง “ต่างกันที่สำนวนภาษา” หรือ “ต่างกันที่ข้อเท็จจริง” แล้วคิดต่อว่าอะไรคือสิ่งที่ระบบทำได้ดี กับอะไรคือสิ่งที่ระบบไม่ได้รับประกัน"},{"id":"1.3.1","q":"เมื่อพิจารณาที่มาของตัวเลขทั้งสอง สาเหตุที่ 40 กับ 52 ต่างกันคือข้อใด","choices":["AI คำนวณผิดเสมอ","ค่าเฉลี่ยจากทุกปีต้องเท่ากัน","กล่องสรุปอ้างหน้าเว็บปี 2566 ส่วนอีกค่ามาจากการวัดจริงสัปดาห์ที่แล้ว","ตัวเลขที่น้อยกว่าย่อมถูกต้อง"],"answer":2,"explain":"ตัวเลขอ้างอิงคนละช่วงเวลา จึงใช้แทนกันไม่ได้ ต้องตรวจวันที่และสถานีให้ตรงกับโจทย์","hint":"ถามว่าคำตอบนี้พาเราไปหาหลักฐานต้นทางได้หรือไม่ ถ้ากดดูแหล่งที่มาไม่ได้เลย ให้ถือว่ายังเป็นข้อมูลที่รอการยืนยัน"},{"id":"1.3.2","q":"เงื่อนไขใดในโจทย์ที่ทำให้ตัวเลขจากกล่องสรุปใช้ไม่ได้ตั้งแต่ต้น","choices":["กล่องสรุปมีข้อความสั้นเกินไป","ต้นใช้เวลาค้นนานกว่า","ข้อมูลจากเว็บไซต์ใช้ไม่ได้ทุกกรณี","โจทย์ขอข้อมูลสัปดาห์ที่แล้ว แต่ต้นทางที่อ้างเป็นข้อมูลปี 2566"],"answer":3,"explain":"เป็นเงื่อนไขที่ชนกับข้อจำกัดของ AI พอดี คือความใหม่ของช่วงเวลาและความจำเป็นต้องอ้างอิงต้นทางได้","hint":"ถามว่าคำตอบนี้พาเราไปหาหลักฐานต้นทางได้หรือไม่ ถ้ากดดูแหล่งที่มาไม่ได้เลย ให้ถือว่ายังเป็นข้อมูลที่รอการยืนยัน"},{"id":"1.4.1","q":"ความผิดพลาดสามครั้งที่ทั้งคู่เจอ เป็นข้อจำกัดคนละแบบ ข้อใดวิเคราะห์ได้ถูกต้อง","choices":["ทั้งสามเหตุการณ์เป็นอาการหลอน","หนังสือคืออาการหลอน งานเดือนที่แล้วคือข้อมูลจำกัดเวลา อาชีพคืออคติ","หนังสือคืออคติ ส่วนอาชีพคือข้อมูลจำกัดเวลา","ทั้งสามเหตุการณ์เป็นเพราะอินเทอร์เน็ตช้า"],"answer":1,"explain":"ของที่ไม่มีอยู่จริงต้องค้นยืนยัน ของที่ยังไม่รู้ต้องดูวันที่ ส่วนของที่รู้ไม่ครบต้องมองหาสิ่งที่หายไป","hint":"แยกสิ่งที่เกิดขึ้นออกเป็น ของที่ไม่มีอยู่จริง, ของที่ยังไม่รู้เพราะเพิ่งเกิด, และของที่รู้ไม่ครบ (หรือ \"แยกคำถามออกเป็นวิธีคิดกับตัวเลข\" ตามการประยุกต์ด่านข้อจำกัด AI)"},{"id":"1.4.2","q":"ในความผิดพลาดทั้งสามครั้ง ข้อใดที่ผู้ใช้มีโอกาสมองข้ามมากที่สุด","choices":["หนังสือ เพราะลิงก์เสียยืนยันว่ามีจริง","รายชื่ออาชีพ เพราะคำตอบดูสมบูรณ์ ไม่มีจุดผิดให้จับได้เลย","งานล่าสุด เพราะ AI ยอมรับข้อจำกัดแล้ว","ทุกกรณีสังเกตง่ายเท่ากัน"],"answer":1,"explain":"ความไม่ครอบคลุมไม่มีอะไรผิดให้เห็น จึงต้องใช้การตั้งคำถามว่ามีใครขาดหายไป","hint":"แยกสิ่งที่เกิดขึ้นออกเป็น ของที่ไม่มีอยู่จริง, ของที่ยังไม่รู้เพราะเพิ่งเกิด, และของที่รู้ไม่ครบ (หรือ \"แยกคำถามออกเป็นวิธีคิดกับตัวเลข\" ตามการประยุกต์ด่านข้อจำกัด AI)"}],"situations":[{"id":"1.1","emoji":"📱","title":"แอปไหนคือ AI กันแน่","difficulty":"ง่าย","context":"คาบแรกวันจันทร์ ครูพริมเขียนบนกระดานว่า “เปิดโทรศัพท์ แล้วเขียนชื่อฟีเจอร์ที่คิดว่าเป็น AI มา 5 อย่าง” ต้นเขียน ฟิลเตอร์แต่งหน้าในแอปวิดีโอสั้น ปุ่มลบคนออกจากรูปในแกลเลอรี คำบรรยายใต้คลิปที่ขึ้นเองอัตโนมัติ น้องเอไอที่เขาใช้ทำการบ้าน และเครื่องคิดเลข มีนาแย้งว่าเครื่องคิดเลขไม่น่าใช่ ต้นเถียงว่า “ก็มันคิดเลขให้เราไง” มีนาจึงกดเครื่องคิดเลข 7 คูณ 8 สามครั้ง ได้ 56 ทุกครั้งไม่ผิดเพี้ยน แล้วพิมพ์ถามน้องเอไอว่า “ขอชื่อโครงงานวิทยาศาสตร์ 3 ชื่อ” สามครั้งด้วยข้อความเดิม ได้ชื่อไม่ซ้ำกันเลยสักครั้ง ครูพริมจึงขีดกระดานเป็นสามช่อง คือ โปรแกรมทั่วไป AI เฉพาะทาง และ AI ที่สร้างของใหม่ แล้วให้ทั้งห้องช่วยกันย้ายรายชื่อลงช่อง","activity":"ลากการ์ดฟีเจอร์ 9 ใบ ไปวางใน 3 ช่องบนกระดาน ระบบบอกเมื่อวางครบว่าช่องใดยังผิดกี่ใบ (แก้ได้ 2 ครั้ง)","hint":"ลองถามตัวเองว่า ถ้าไม่มีข้อมูลตัวอย่างให้เรียนรู้ โปรแกรมนี้ยังทำงานได้หรือไม่ และผลลัพธ์ที่ได้เป็นการเลือกจากของที่มีอยู่แล้ว หรือเป็นของใหม่ที่เพิ่งถูกสร้างขึ้น","learning":"ปัญญาประดิษฐ์คือระบบที่เรียนรู้รูปแบบจากข้อมูลเพื่อทำงานที่ปกติต้องใช้ความสามารถของมนุษย์ ต่างจากโปรแกรมทั่วไปที่ทำงานตามชุดคำสั่งตายตัว ปัญญาประดิษฐ์แบ่งได้หลายประเภท เช่น AI เชิงทำนายหรือจำแนก และ Generative AI ที่สร้างเนื้อหาใหม่ (คำว่า “ปัญญาประดิษฐ์” ถูกใช้อย่างเป็นทางการครั้งแรกเมื่อปี ค.ศ. 1956)","place":"ห้องเรียนของครูพริม","videoUrl":"https://dearchotirat40.github.io/aware-ai-guardian-academy/public/scenario-1-1.mp4","contentRevision":4,"storyScenes":[{"speaker":"ครูพริม","text":"เปิดโทรศัพท์ แล้วเขียนฟีเจอร์ที่คิดว่าเป็น AI มา 5 อย่าง","emoji":"🧑‍🏫"},{"speaker":"ต้น","text":"ฟิลเตอร์แต่งหน้า ลบคนออกจากรูป คำบรรยายอัตโนมัติ น้องเอไอ และเครื่องคิดเลข!","emoji":"👦"},{"speaker":"มีนา","text":"เครื่องคิดเลข 7 × 8 ได้ 56 ทุกครั้ง แต่น้องเอไอตั้งชื่อโครงงานใหม่ได้หลายแบบ","emoji":"👧"},{"speaker":"ครูพริม","text":"ลองแยกลง 3 ช่อง: โปรแกรมทั่วไป · AI เฉพาะทาง · AI สร้างของใหม่","emoji":"🧩"}],"activityData":{"groups":["โปรแกรมทั่วไป","AI ทำนาย / จำแนก","AI สร้างเนื้อหาใหม่"],"cards":[{"text":"เครื่องคิดเลข","answer":0},{"text":"นาฬิกาปลุกตามเวลาที่ตั้ง","answer":0},{"text":"แปลงเซลเซียสเป็นฟาเรนไฮต์ตามสูตร","answer":0},{"text":"แนะนำเพลงจากประวัติการฟัง","answer":1},{"text":"กรองสแปมจากรูปแบบอีเมล","answer":1},{"text":"รู้จำเสียงพูดเป็นคำบรรยาย","answer":1},{"text":"สร้างภาพจากข้อความ","answer":2},{"text":"แชตบอตสร้างชื่อโครงงาน","answer":2},{"text":"สร้างมิวสิกวิดีโอใหม่","answer":2}],"maxAttempts":3}},{"id":"1.2","emoji":"💬","title":"ถามเหมือนเดิม แต่ตอบไม่เหมือนเดิม","difficulty":"ปานกลาง","context":"ต้นพิมพ์ถามน้องเอไอว่า “แนะนำหัวข้อโครงงานวิทยาศาสตร์ ม.4” แล้วกดปุ่มถามซ้ำอีกสองครั้งโดยไม่แก้ข้อความเลย ปรากฏว่าทั้งสามครั้งได้หัวข้อไม่เหมือนกัน มีซ้ำกันแค่บางหัวข้อ ต้นจึงสรุปว่า “มันสุ่มจากลิสต์ เหมือนจับฉลากนั่นแหละ” มีนายังไม่ปักใจเชื่อ จึงลองทดสอบแบบที่ง่ายกว่า เธอพิมพ์ประโยคที่ยังไม่จบว่า “วันนี้อากาศร้อน ฉันจึงอยาก” แล้วให้น้องเอไอเติมคำต่อท้าย 5 ครั้ง ได้คำว่า ดื่ม ว่าย นอน กิน และอาบ ทั้งห้าคำไม่ซ้ำกัน แต่ทุกคำเข้ากับประโยคได้อย่างสมเหตุสมผล ส่วนคำที่ขัดกับอากาศร้อนอย่าง ใส่เสื้อกันหนาว ไม่โผล่มาเลยสักครั้ง ครูพริมเห็นผลการทดลอง จึงชวนทั้งคู่คิดว่า ผลแบบนี้บอกอะไรเกี่ยวกับวิธีที่น้องเอไอเลือกคำ","activity":"ทดลองถามข้อความเดิม 3 ครั้ง แล้วเติมประโยค “วันนี้อากาศร้อน ฉันจึงอยาก” 5 ครั้ง สังเกตคำตอบที่ได้","hint":"ลองแยกให้ออกว่าคำตอบทั้งสามครั้ง “ต่างกันที่สำนวนภาษา” หรือ “ต่างกันที่ข้อเท็จจริง” แล้วคิดต่อว่าอะไรคือสิ่งที่ระบบทำได้ดี กับอะไรคือสิ่งที่ระบบไม่ได้รับประกัน","learning":"โมเดลภาษาไม่ได้ประมวลผลทีละคำเต็ม ๆ แต่ตัดข้อความออกเป็นหน่วยย่อยเรียกว่า token ซึ่งอาจเป็นเพียงส่วนหนึ่งของคำ ภาษาไทยมักถูกตัดเป็นจำนวน token ต่อประโยคมากกว่าภาษาอังกฤษ เพราะไม่มีช่องว่างระหว่างคำ","place":"ห้องเรียนของครูพริม","videoUrl":"","imageUrl":"https://dearchotirat40.github.io/aware-ai-guardian-academy/public/scenario-1-2.png","imageAlt":"สถานการณ์ที่ 1.2 ถามเหมือนเดิม แต่ตอบไม่เหมือนเดิม: ต้นถามซ้ำ 3 ครั้ง มีนาทดลองเติมคำ 5 ครั้ง และครูพริมชวนคิด","contentRevision":2,"activityData":{"prompt":"แนะนำหัวข้อโครงงานวิทยาศาสตร์ ม.4","sentence":"วันนี้อากาศร้อน ฉันจึงอยาก","outputs":["การศึกษาการเจริญเติบโตของพืช · การลดขยะพลาสติกในโรงเรียน · ผลของแสงต่อการสังเคราะห์แสง · การสำรวจคุณภาพน้ำในชุมชน · การใช้พลังงานทดแทนในโรงเรียน","การศึกษาการเจริญเติบโตของพืช · สมบัติการดูดซับของถ่านกัมมันต์ · การพัฒนาผลิตภัณฑ์จากวัสดุเหลือใช้ · การตรวจวัดคุณภาพอากาศ · ผลของอุณหภูมิต่อการงอกของเมล็ด","การเพาะเลี้ยงจุลินทรีย์ในอาหาร · การลดขยะพลาสติกในโรงเรียน · การพัฒนาพลังงานจากกากพืช · การตรวจวัดคุณภาพน้ำในชุมชน · การใช้สมุนไพรในการยับยั้งเชื้อแบคทีเรีย"],"words":["ดื่ม","ว่าย","นอน","กิน","อาบ"],"note":"คำตัวอย่างชุดนี้ออกแบบสำหรับบริบทอากาศร้อน ลองสังเกตว่าคำเข้ากับประโยคที่คุณพิมพ์หรือไม่"},"storyScenes":[{"speaker":"ต้น","text":"แนะนำหัวข้อโครงงานวิทยาศาสตร์ ม.4 — ถามเหมือนเดิม 3 ครั้ง ทำไมได้หัวข้อต่างกัน?","emoji":"👦"},{"speaker":"มีนา","text":"ลองเติมประโยค “วันนี้อากาศร้อน ฉันจึงอยาก” ซ้ำ 5 ครั้งกัน","emoji":"👧"},{"speaker":"น้องเอไอ","text":"ดื่ม · ว่าย · นอน · กิน · อาบ","emoji":"🤖"},{"speaker":"ครูพริม","text":"คำแตกต่างกัน แต่เข้ากับบริบท ผลนี้บอกอะไรเกี่ยวกับการเลือกคำ?","emoji":"🧑‍🏫"}]},{"id":"1.3","emoji":"🔎","title":"ข่าวเมื่อวานที่น้องเอไอไม่รู้","difficulty":"ค่อนข้างยาก","context":"วิชาสังคมศึกษาสั่งรายงานค่าฝุ่น PM2.5 เขตสายไหม “ของสัปดาห์ที่ผ่านมา” กำหนดส่งวันศุกร์ มีนาพิมพ์คำค้นในเครื่องมือค้นหา แล้วอ่านกล่องสรุปคำตอบที่ AI เขียนไว้บนสุดของหน้า ได้ค่าเฉลี่ยราว 40 ไมโครกรัมต่อลูกบาศก์เมตร เธอคัดลอกตัวเลขนั้นลงรายงานทันทีโดยไม่ได้กดลิงก์ใด ส่วนต้นเลื่อนผ่านกล่องสรุปลงไปกดลิงก์ต้นทางที่อ้างไว้ใต้กล่อง พบว่าหน้านั้นเป็นข้อมูลของปี 2566 ไม่ใช่สัปดาห์ที่ผ่านมา เขาจึงเข้าเว็บหน่วยงานโดยตรงและพบตารางรายวันพร้อมชื่อสถานีตรวจวัดและวันที่เผยแพร่ เมื่อเฉลี่ยเจ็ดวันได้ 52 ไมโครกรัมต่อลูกบาศก์เมตร เหลือเวลาอีกสองวัน ทั้งคู่ต้องตัดสินใจว่าจะใช้ตัวเลขใด","activity":"กดลิงก์ใต้กล่องสรุปคำตอบของ AI แล้วหาวันที่เผยแพร่ในหน้าเว็บต้นทางให้เจอ","hint":"ถามว่าคำตอบนี้พาเราไปหาหลักฐานต้นทางได้หรือไม่ ถ้ากดดูแหล่งที่มาไม่ได้เลย ให้ถือว่ายังเป็นข้อมูลที่รอการยืนยัน","learning":"เครื่องมือค้นหาทำหน้าที่ชี้ไปยังหน้าเว็บต้นทางที่ระบุผู้เผยแพร่และวันที่ได้ ส่วน Generative Al อาจไม่ครอบคลุมเหตุการณ์ล่าสุดและมักไม่มีแหล่งอ้างอิง ข้อมูลตัวเลขทางการจึงต้องยืนยันจากแหล่งต้นทางเสมอ","place":"ห้องเรียนของครูพริม","videoUrl":"","mediaType":"chat","contentRevision":1,"storyScenes":[{"speaker":"ครูพริม","text":"รายงานสังคมศึกษาครั้งนี้ หาค่า PM2.5 เขตสายไหมของสัปดาห์ที่ผ่านมา ส่งวันศุกร์นะ","emoji":"🧑‍🏫"},{"speaker":"มีนา","text":"เราค้นแล้ว! กล่องสรุป AI บนสุดบอกเฉลี่ยประมาณ 40 ไมโครกรัมต่อลูกบาศก์เมตร","emoji":"👧"},{"speaker":"มีนา","text":"คัดลอก 40 ลงรายงานแล้ว ยังไม่ได้กดลิงก์ไหนเลย","emoji":"👧"},{"speaker":"ต้น","text":"เดี๋ยวก่อน เรากดลิงก์ต้นทางใต้กล่องแล้ว ข้อมูลเป็นปี 2566 ไม่ใช่สัปดาห์ที่ผ่านมา","emoji":"👦"},{"speaker":"มีนา","text":"อ้าว แล้วข้อมูลของสัปดาห์ที่ผ่านมาดูตรงไหน?","emoji":"👧"},{"speaker":"ต้น","text":"เราเข้าเว็บหน่วยงานโดยตรง มีตารางรายวัน ชื่อสถานีตรวจวัด และวันที่เผยแพร่ครบ","emoji":"👦"},{"speaker":"ต้น","text":"พอเฉลี่ยข้อมูลทั้ง 7 วัน ได้ 52 ไมโครกรัมต่อลูกบาศก์เมตร","emoji":"👦"},{"speaker":"มีนา","text":"เหลืออีกสองวันก่อนส่งวันศุกร์ เราจะใช้ 40 หรือ 52 แล้วควรตรวจอะไรอีก?","emoji":"👧"}],"activityData":{"summary":"AI สรุป: ค่า PM2.5 เฉลี่ยประมาณ 40 ไมโครกรัมต่อลูกบาศก์เมตร","sourceTitle":"หน้าต้นทางจำลอง: รายงาน PM2.5 เขตสายไหม","published":"เผยแพร่: 15 ธันวาคม 2566 · ค่าเฉลี่ย 40 ไมโครกรัมต่อลูกบาศก์เมตร","comparison":"ตารางอีกแหล่งในเรื่อง: สถานีสายไหม สัปดาห์ที่ผ่านมา 48, 50, 52, 54, 56, 51, 53 → เฉลี่ย 52","question":"ต้นทางของค่า 40 เผยแพร่ปีใด?","options":["2566","2569"],"correctValue":"2566","success":"✓ ถูกต้อง ต้นทางเป็นปี 2566 จึงใช้แทนสัปดาห์ที่ผ่านมาไม่ได้","retry":"ลองดูปีที่เผยแพร่บนหน้าต้นทางอีกครั้ง"}},{"id":"1.4","emoji":"📚","title":"หนังสือที่ไม่มีในห้องสมุด","difficulty":"ยาก","context":"เย็นวันอังคาร ต้นกับมีนาทำรายงานเรื่องแหล่งเรียนรู้ในจังหวัด ต้นขอชื่อหนังสืออ้างอิง น้องเอไอตอบว่า “คู่มือแหล่งเรียนรู้ชุมชน สำนักพิมพ์ครูไทย พ.ศ. 2563” พร้อมแนบลิงก์ร้านหนังสือออนไลน์มาให้ด้วย ดูน่าเชื่อถือมาก แต่พอมีนากดลิงก์กลับขึ้นหน้าว่าไม่พบสินค้า และค้นชื่อเรื่องในระบบห้องสมุดโรงเรียนกับหอสมุดแห่งชาติก็ไม่พบทั้งสองที่ ต่อมามีนาถามถึงงานเปิดบ้านของจังหวัดที่เพิ่งจัดเมื่อเดือนที่แล้ว คราวนี้น้องเอไอไม่ได้เปิดการค้นเว็บ จึงตอบว่ายืนยันข้อมูลล่าสุดไม่ได้ และเมื่อขอตัวอย่างอาชีพในท้องถิ่น 10 อาชีพ คำตอบที่ได้เป็นโปรแกรมเมอร์ นักการตลาด และพนักงานธนาคารเสียส่วนใหญ่ ไม่มีช่างซ่อมมอเตอร์ไซค์หรือแม่ค้าตลาดนัดที่ทั้งคู่เดินผ่านทุกวันเลยสักอาชีพ","activity":"ลากเหตุการณ์ผิดพลาด 3 เหตุการณ์ (หนังสือ, งานเดือนที่แล้ว, อาชีพ) ไปจับคู่กับข้อจำกัด (อาการหลอน, ข้อมูลจำกัดเวลา, อคติจากข้อมูลฝึก)","hint":"แยกสิ่งที่เกิดขึ้นออกเป็น ของที่ไม่มีอยู่จริง, ของที่ยังไม่รู้เพราะเพิ่งเกิด, และของที่รู้ไม่ครบ (หรือ \"แยกคำถามออกเป็นวิธีคิดกับตัวเลข\" ตามการประยุกต์ด่านข้อจำกัด AI)","learning":"Hallucination คือการที่ AI สร้างข้อมูลหรือแหล่งอ้างอิงที่ไม่มีหลักฐานรองรับ แม้คำตอบจะดูมั่นใจ จึงควรตรวจสอบกับแหล่งจริง รวมทั้งตรวจวันที่และมุมมองที่อาจขาดหายไป","place":"ห้องเรียนของครูพริม","videoUrl":"","storyScenes":[{"speaker":"น้องเอไอ","text":"ลองอ้าง “คู่มือแหล่งเรียนรู้ชุมชน สำนักพิมพ์ครูไทย พ.ศ. 2563”","emoji":"🤖"},{"speaker":"มีนา","text":"ลิงก์เปิดไม่พบสินค้า และค้นชื่อหนังสือในห้องสมุดไม่พบทั้งสองแห่ง","emoji":"👧"},{"speaker":"น้องเอไอ","text":"ยังยืนยันงานเดือนที่แล้วไม่ได้เมื่อไม่ได้ค้นเว็บ ส่วนอาชีพแนะนำ: โปรแกรมเมอร์ นักการตลาด พนักงานธนาคาร","emoji":"🤖"},{"speaker":"ต้น","text":"แล้วช่างซ่อมมอเตอร์ไซค์กับแม่ค้าตลาดนัดล่ะ? ลองแยกข้อจำกัดทั้ง 3 แบบกัน","emoji":"👦"}],"activityData":{"groups":["อาการหลอน","ข้อมูลจำกัดเวลา","อคติจากข้อมูลฝึก"],"cards":[{"text":"หนังสือและลิงก์ที่ค้นไม่พบ","answer":0},{"text":"ยืนยันงานเดือนที่แล้วไม่ได้เมื่อไม่ค้นเว็บ","answer":1},{"text":"รายชื่ออาชีพขาดอาชีพในชุมชน","answer":2}],"maxAttempts":0}}],"unitOneRevision":1,"flowSettings":{"welcomeTitle":"ฐานที่ 1 ห้องแยกประเภท","welcomeText":"รู้จัก AI ผ่าน 4 เหตุการณ์ของต้น มีนา และครูพริม","awardTitle":"นักสำรวจ AI","hintSeconds":60},"_key":"lesson-1"},{"title":"บทที่ 2: เลือกและใช้ AI อย่างเหมาะสม","short":"เลือกใช้ AI","mission":{"name":"หน่วยที่ 2: เลือกและใช้ AI อย่างเหมาะสม","role":"ต้น มีนา ครูพริม และน้องเอไอ","goal":"เลือกเครื่องมือให้ตรงงาน เขียนและปรับพรอมต์อย่างมีเป้าหมาย และใช้ AI โดยยังเป็นเจ้าของผลงานของตนเอง"},"simulation":{"place":"งานกลุ่มเรื่องขยะพลาสติก","context":"กลุ่มของมีนาต้องสรุปบทความ ออกแบบภาพปก สร้างกราฟจากข้อมูลขยะที่เก็บ 4 สัปดาห์ และตรวจภาษาอังกฤษ ต้นอยากให้น้องเอไอทำทั้งหมด แต่กราฟที่ AI สร้างมีตัวเลขไม่ตรงกับข้อมูลจริงเพราะ AI ประมาณค่าแทน","task":"เลือกเครื่องมือให้ตรงงาน เขียนและปรับพรอมต์อย่างมีเป้าหมาย และใช้ AI โดยยังเป็นเจ้าของผลงานของตนเอง"},"videoDesc":"คลิปสั้น: “เลือกเครื่องมือและเขียน Prompt ให้ได้งาน” — เลือก AI ตามงาน เขียนพรอมต์ให้ชัด ปรับคำสั่ง และใช้ AI ในงานเรียนอย่างมีขอบเขต","slides":[{"emoji":"🧰","title":"เลือก AI ให้ตรงกับงาน","text":"เริ่มจากถามว่าเราต้องการทำอะไร เช่น ค้นข้อมูล สรุปข้อความ ระดมความคิด สร้างภาพ หรือวิเคราะห์ตาราง แล้วเลือกเครื่องมือที่เหมาะกับงาน ความน่าเชื่อถือ และความเป็นส่วนตัว ไม่จำเป็นต้องใช้เครื่องมือที่กำลังเป็นกระแสเสมอไป"},{"emoji":"✍️","title":"พรอมต์ที่ดีมีองค์ประกอบอะไร?","text":"บอกให้ชัด 4 ส่วน: บทบาทของ AI · งานที่ให้ทำ · บริบทหรือเงื่อนไข · รูปแบบผลลัพธ์ ตัวอย่าง “ช่วยเป็นติวเตอร์สรุปเรื่อง… สำหรับ ม.4 เป็น 5 ข้อ ใช้ภาษาง่าย” คำสั่งที่ชัดทำให้ได้ผลลัพธ์ตรงเป้าหมายขึ้น"},{"emoji":"🔁","title":"ปรับพรอมต์แบบวนซ้ำ","text":"คำตอบครั้งแรกเป็นจุดเริ่มต้น อ่านแล้วบอก AI ว่าอยากให้แก้เรื่องใด เช่น ใช้ภาษาง่ายขึ้น เพิ่มตัวอย่าง ลดความยาว หรือจัดเป็นตาราง การลอง–ตรวจ–ปรับ ช่วยให้เราใช้ AI อย่างมีเป้าหมาย"},{"emoji":"🤝","title":"AI เป็นผู้ช่วย ไม่ใช่ผู้ทำงานแทน","text":"AI ช่วยวางโครงหรือเสนอไอเดียได้ แต่นักเรียนต้องตรวจ แก้ไข และเรียบเรียงด้วยตนเอง ไม่คัดลอกส่งเป็นผลงานของตนเอง และทำตามกติกาของครูทุกครั้ง"}],"quiz":[{"q":"งานสร้างกราฟจากข้อมูลขยะที่กลุ่มเก็บเอง ควรใช้เครื่องมือใดเป็นหลัก?","choices":["โปรแกรมตารางคำนวณที่ใช้ข้อมูลจริง","AI สร้างภาพ","แชตบอตที่เดาตัวเลขให้สมเหตุสมผล","เครื่องมือแปลภาษา"],"answer":0,"hint":"งานนี้ต้องรักษาความถูกต้องของตัวเลขจริง","explain":"โปรแกรมตารางคำนวณเหมาะกับการประมวลผลข้อมูลจริง ขณะที่ AI ใช้ช่วยอธิบายหรือสรุปได้"},{"q":"ข้อใดเป็นพรอมต์ที่ครบองค์ประกอบมากที่สุด?","choices":["สรุปเรื่องโลกร้อนให้หน่อย","เป็นติวเตอร์ ช่วยสรุปโลกร้อนสำหรับ ม.4 เป็น 5 หัวข้อ ใช้ภาษาง่าย ไม่เกิน 250 คำ และไม่ใช้ศัพท์เทคนิค","ทำให้สวยและเร็ว","เขียนอะไรก็ได้เกี่ยวกับโลกร้อน"],"answer":1,"hint":"มองหาบทบาท งาน กลุ่มผู้อ่าน รูปแบบ และข้อจำกัด","explain":"คำสั่งนี้ระบุบทบาท งาน กลุ่มเป้าหมาย รูปแบบ ความยาว และข้อจำกัดชัดเจน"},{"q":"ถ้าบทพูด AI ยาวเกินเวลาและตัดข้อมูลสำคัญเมื่อสั่งให้สั้นลง ควรทำอย่างไร?","choices":["เลิกใช้ AI ทันที","ระบุเวลา น้ำเสียง และข้อมูลที่ห้ามตัด แล้วปรับทีละจุด","ส่งข้อความเดิมโดยไม่อ่าน","ให้ AI เลือกข้อมูลสำคัญเอง"],"answer":1,"hint":"การปรับพรอมต์ที่ดีต้องบอกสิ่งที่ยังไม่ตรงอย่างเฉพาะเจาะจง","explain":"การระบุเงื่อนไขที่วัดได้และข้อมูลห้ามตัดช่วยให้การปรับรอบต่อไปตรงเป้าหมาย"},{"q":"ข้อใดเป็นการใช้ AI ในงานเรียงความอย่างเหมาะสม?","choices":["ให้ AI เขียนแทนทั้งหมดแล้วส่งชื่อเรา","ใช้ AI ช่วยตั้งคำถามหรือวางโครง แล้วเขียนและตรวจจากประสบการณ์ของตน","คัดลอกคำตอบ AI โดยไม่อ่าน","ให้เพื่อนส่งงานที่ AI เขียนแทน"],"answer":1,"hint":"งานสะท้อนคิดต้องแสดงความคิดและประสบการณ์ของผู้เรียน","explain":"AI เป็นผู้ช่วยได้ แต่ผู้เรียนต้องเป็นเจ้าของความคิด การเขียน และผลงานที่ส่ง"}],"situations":[{"id":"2.1","emoji":"🧰","title":"งานเดียวแต่ต้องใช้หลายเครื่องมือ","place":"งานกลุ่มเรื่องขยะพลาสติก","context":"กลุ่มของมีนาต้องสรุปบทความ ออกแบบภาพปก สร้างกราฟจากข้อมูลขยะที่เก็บ 4 สัปดาห์ และตรวจภาษาอังกฤษ ต้นอยากให้น้องเอไอทำทั้งหมด แต่กราฟที่ AI สร้างมีตัวเลขไม่ตรงกับข้อมูลจริงเพราะ AI ประมาณค่าแทน","issue":"เครื่องมือเดียวเหมาะกับทุกงานหรือไม่ และควรใช้เกณฑ์ใดเลือก","learning":"เลือกเครื่องมือตามลักษณะงาน ความถูกต้องที่ต้องการ ความสามารถตรวจย้อนกลับ และกติกาโรงเรียน ใช้ตารางคำนวณกับข้อมูลจริง ใช้ AI ช่วยสรุป เรียบเรียง หรือเริ่มไอเดีย","hint":"แยกว่างานนั้นต้องการความถูกต้องของข้อมูลจริง หรือความคิดสร้างสรรค์เป็นหลัก","videoUrl":""},{"id":"2.2","emoji":"✍️","title":"จากคำสั่ง “ทำให้หน่อย” สู่พรอมต์ที่ใช้งานได้","place":"การเตรียมอภิปรายเรื่องโลกร้อน","context":"มีนาให้ AI “สรุปให้หน่อย” จึงได้ข้อความยาว มีศัพท์ยาก และไม่ทันนำเสนอ 5 นาที ครูพริมจึงเขียนคำถามว่า “ใครอ่าน ใช้ทำอะไร ยาวเท่าไร หน้าตาแบบไหน ห้ามมีอะไร” เพื่อให้มีนาเขียนคำสั่งใหม่","issue":"พรอมต์ที่ดีควรบอกอะไรกับ AI","learning":"พรอมต์ที่ดีระบุบทบาท งาน บริบทหรือกลุ่มผู้อ่าน รูปแบบผลลัพธ์ และข้อจำกัด ยิ่งชัดยิ่งได้คำตอบตรงงานและลดรอบแก้","hint":"อ่านคำสั่งของตนเองเหมือนเป็นเพื่อนที่ไม่รู้จักงานนี้ แล้วดูว่าจะทำงานออกมาตรงที่ต้องการหรือไม่","videoUrl":""},{"id":"2.3","emoji":"🔁","title":"ปรับพรอมต์รอบที่สาม","place":"เสียงตามสายโรงเรียน","context":"ต้นสั่ง AI เขียนบทพูดแนะนำชมรมถ่ายภาพ 1 นาที รอบแรกเป็นทางการและยาวเกือบ 3 นาที รอบสองสั่งให้สั้นลงแต่ AI ตัดวันเวลารับสมัครออก ครูพริมแนะนำให้จดจุดที่ยังไม่ดีแล้วแก้คำสั่งทีละจุด","issue":"เมื่อผลลัพธ์ไม่ตรงเป้าหมาย ควรปรับคำสั่งอย่างไร","learning":"ปรับพรอมต์แบบวนซ้ำโดยระบุปัญหาเป็นข้อ ๆ เช่น จำนวนคำ เวลา น้ำเสียง กลุ่มผู้ฟัง ข้อมูลห้ามตัด และรูปแบบผลลัพธ์ พร้อมบันทึกผลของการแก้แต่ละรอบ","hint":"อย่าเริ่มใหม่ทั้งหมด ให้ระบุสิ่งที่ยังไม่ตรงและเพิ่มเงื่อนไขที่วัดได้ทีละข้อ","videoUrl":""},{"id":"2.4","emoji":"📝","title":"เส้นแบ่งในงานเรียงความ","place":"งานเขียนสะท้อนคิด","context":"ต้นต้องเขียนเรียงความสะท้อนคิดเรื่องการใช้โทรศัพท์ในชีวิตประจำวัน เขาอยากให้ AI เขียนแทนทั้งหมดเพราะคิดว่าแค่ส่งตรงเวลา มีนาชวนให้ใช้ AI ช่วยตั้งคำถามหรือวางโครง แล้วเขียนจากประสบการณ์ของตนเองตามกติกาของครู","issue":"งานใดควรใช้ AI ช่วยได้ และงานใดไม่ควรให้ AI ทำแทน","learning":"AI ช่วยระดมความคิด วางโครง ตรวจภาษา หรืออธิบายเรื่องยากได้ แต่ไม่ควรทำแทนงานที่วัดประสบการณ์ ความคิด และทักษะของผู้เรียน ต้องทำตามกติกาครูและเป็นเจ้าของงานจริง","hint":"ถามว่างานนี้กำลังวัดความรู้หรือประสบการณ์ของใคร หากวัดของเรา AI ไม่ควรเขียนแทน","videoUrl":""}],"_key":"lesson-2"},{"title":"บทที่ 3: ตรวจสอบและประเมินข้อมูลจาก AI","short":"ตรวจคำตอบ AI","mission":{"name":"หน่วยที่ 3: ตรวจสอบและประเมินข้อมูลจาก AI","role":"ต้น มีนา ครูพริม และน้องเอไอ","goal":"รู้เท่าทันข้อมูลที่ดูน่าเชื่อ ตรวจหลักฐาน ประเมินแหล่งข้อมูล และมองหามุมมองที่อาจหายไป"},"simulation":{"place":"การค้นคว้ารายงาน","context":"มีนาขอให้น้องเอไอหาเอกสารอ้างอิงเรื่องการนอนของวัยรุ่น AI ให้ชื่อบทความ ผู้เขียน วารสาร ปี และ DOI ครบ แต่ต้นค้นในฐานข้อมูลวิชาการแล้วไม่พบแม้แต่รายการเดียว น้องเอไอยังเสนอให้ “ปรับรูปแบบอ้างอิง” แทนการยืนยันแหล่งจริง","task":"รู้เท่าทันข้อมูลที่ดูน่าเชื่อ ตรวจหลักฐาน ประเมินแหล่งข้อมูล และมองหามุมมองที่อาจหายไป"},"videoDesc":"คลิปสั้น: “ตรวจคำตอบ AI ก่อนเชื่อและแชร์” — รู้ทัน Hallucination ตรวจข้ามแหล่ง ประเมินความน่าเชื่อถือ และมองหาอคติหรือมุมมองที่หายไป","slides":[{"emoji":"🌀","title":"AI อาจเดาเก่งแต่ตอบผิดได้","text":"บางครั้ง AI สร้างชื่อคน ตัวเลข เหตุการณ์ หรือแหล่งอ้างอิงที่ไม่มีอยู่จริง และเขียนให้น่าเชื่อ ปรากฏการณ์นี้เรียกว่า Hallucination จึงอย่าใช้คำตอบจาก AI เป็นข้อเท็จจริงทันที โดยเฉพาะข้อมูลสำคัญ"},{"emoji":"🔍","title":"ตรวจสอบข้ามแหล่ง","text":"แยกคำกล่าวอ้างสำคัญ เช่น ตัวเลข วันที่ ชื่อบุคคล หรือข้อสรุป แล้วเปรียบเทียบกับแหล่งต้นฉบับหรือแหล่งน่าเชื่อถืออย่างน้อย 2 แหล่ง เช่น หน่วยงานรัฐ มหาวิทยาลัย หนังสือเรียน หรือบทความวิชาการ"},{"emoji":"🧭","title":"ดูอย่างไรว่าแหล่งข้อมูลน่าเชื่อถือ?","text":"พิจารณาผู้เขียนหรือหน่วยงาน วันที่เผยแพร่ หลักฐานที่อ้างอิง และจุดประสงค์ของเนื้อหา แหล่งที่มีชื่อชัดและตรวจย้อนกลับได้ น่าเชื่อถือกว่าข้อความที่ไม่มีที่มา"},{"emoji":"⚖️","title":"มองหาอคติและมุมที่หายไป","text":"ข้อมูลที่ AI เรียนรู้มาอาจไม่ครอบคลุมทุกกลุ่มหรือทุกมุมมอง ลองถามว่า “ใครเป็นผู้ให้ข้อมูล?” “ใครอาจไม่ได้ถูกพูดถึง?” แล้วเปรียบเทียบหลายแหล่งก่อนสรุปหรือแชร์"}],"quiz":[{"q":"เมื่อ AI ให้บทความอ้างอิงพร้อม DOI แต่ค้นในฐานข้อมูลไม่พบ ควรทำอย่างไร?","choices":["ใช้อ้างอิงได้เพราะรายละเอียดครบ","ตัดออกและค้นหาแหล่งจริงที่ตรวจสอบย้อนกลับได้","เปลี่ยน DOI ให้ดูสั้นลง","ถาม AI ให้ยืนยันว่าไม่ผิด"],"answer":1,"hint":"การอ้างอิงที่ใช้ได้ต้องหาแหล่งต้นฉบับพบ","explain":"AI อาจสร้างรายการอ้างอิงขึ้นมาเอง จึงต้องตรวจฐานข้อมูลหรือเว็บไซต์วารสารเสมอ"},{"q":"ก่อนใช้สถิติ “ร้อยละ 87” ควรตรวจข้อมูลใด?","choices":["สีของอินโฟกราฟิก","ผู้เผยแพร่ ปี กลุ่มตัวอย่าง วิธีเก็บข้อมูล และแหล่งต้นฉบับ","จำนวนครั้งที่คนแชร์","ความยาวของข้อความ AI"],"answer":1,"hint":"สถิติที่น่าเชื่อถือต้องมีที่มาและวิธีการ","explain":"ข้อมูลเหล่านี้ทำให้เราประเมินได้ว่าตัวเลขนั้นใช้กับใครและเชื่อถือได้เพียงใด"},{"q":"แหล่งใดควรมีน้ำหนักมากที่สุดสำหรับรายงาน?","choices":["โพสต์ไม่ระบุผู้เขียน","บล็อกขายคอร์สที่ไม่มีหลักฐาน","เว็บไซต์หน่วยงานการศึกษาที่ระบุผู้รับผิดชอบ วันที่ และแหล่งอ้างอิง","ข้อความที่ AI เขียนเอง"],"answer":2,"hint":"ดูผู้รับผิดชอบ หลักฐาน และการตรวจย้อนกลับ","explain":"แหล่งที่ระบุหน่วยงาน ผู้รับผิดชอบ วันที่ และหลักฐานชัดเจน น่าเชื่อถือกว่า"},{"q":"วิธีใดช่วยลดการตกหล่นของมุมมองในคำตอบ AI?","choices":["ถามคำถามเดิมซ้ำอย่างเดียว","ถามมุมตรงข้ามและผลกระทบต่อกลุ่มต่าง ๆ","เลือกเฉพาะคำตอบที่เห็นด้วยกับเรา","ไม่ต้องดูบริบทของผู้ใช้"],"answer":1,"hint":"ตั้งคำถามให้เห็นหลายฝ่ายและหลายบริบท","explain":"การถามมุมตรงข้ามและกลุ่มที่อาจไม่ได้ถูกพูดถึง ช่วยให้ประเมินอคติและช่องว่างของคำตอบได้"}],"situations":[{"id":"3.1","emoji":"📚","title":"งานวิจัยที่ไม่มีอยู่จริง","place":"การค้นคว้ารายงาน","context":"มีนาขอให้น้องเอไอหาเอกสารอ้างอิงเรื่องการนอนของวัยรุ่น AI ให้ชื่อบทความ ผู้เขียน วารสาร ปี และ DOI ครบ แต่ต้นค้นในฐานข้อมูลวิชาการแล้วไม่พบแม้แต่รายการเดียว น้องเอไอยังเสนอให้ “ปรับรูปแบบอ้างอิง” แทนการยืนยันแหล่งจริง","issue":"รายการอ้างอิงที่ดูสมบูรณ์เชื่อถือได้เพียงใด","learning":"AI อาจสร้างการอ้างอิงที่ไม่มีอยู่จริง ต้องตรวจชื่อเรื่อง ผู้เขียน DOI และฐานข้อมูลหรือเว็บไซต์วารสารก่อนใช้ ห้ามอ้างอิงแหล่งที่ตรวจไม่พบ","hint":"ชื่อผู้เขียน ปี และ DOI ดูเป็นทางการได้ แต่ต้องค้นย้อนกลับถึงบทความจริงเสมอ","videoUrl":""},{"id":"3.2","emoji":"📊","title":"ตัวเลขร้อยละ 87 ที่ไม่มีเจ้าของ","place":"การทำอินโฟกราฟิก","context":"ต้นให้ AI สรุปข้อมูลเรื่องการใช้สื่อสังคมของวัยรุ่น และได้ประโยคว่า “ร้อยละ 87 ของนักเรียนใช้ก่อนนอน” แต่ไม่มีหน่วยงาน ปี กลุ่มตัวอย่าง หรือวิธีสำรวจ มีนาพบตัวเลขใกล้เคียงในหลายโพสต์ที่ลอกต่อกัน แต่หาแหล่งต้นฉบับไม่พบ","issue":"ตัวเลขที่ถูกแชร์ซ้ำมีความน่าเชื่อถือเพียงใด","learning":"ตรวจตัวเลขกับแหล่งอิสระอย่างน้อย 2 แหล่ง ดูผู้เผยแพร่ ปี กลุ่มตัวอย่าง และวิธีเก็บข้อมูล หากยืนยันไม่ได้ให้ตัดออกหรือระบุข้อจำกัด ไม่ควรทำให้ตัวเลขดูจริงเพียงเพราะพบซ้ำ","hint":"ถามว่าใครเก็บข้อมูล เมื่อไร สำรวจใครกี่คน และลิงก์ไปยังรายงานต้นฉบับได้หรือไม่","videoUrl":""},{"id":"3.3","emoji":"🔗","title":"สามลิงก์ที่น้ำหนักไม่เท่ากัน","place":"การเลือกหลักฐาน","context":"ครูพริมให้กลุ่มของต้นหาหลักฐานเรื่องการใช้ AI ในการศึกษา น้องเอไอเสนอทั้งเว็บไซต์หน่วยงานการศึกษา บทความบล็อกขายคอร์ส และโพสต์ไม่ระบุผู้เขียน ทั้งสามลิงก์พูดข้อมูลคล้ายกัน แต่น้ำหนักของหลักฐานต่างกันมาก","issue":"แหล่งข้อมูลใดควรมีน้ำหนักมากกว่า และดูจากอะไร","learning":"ประเมินผู้เขียนหรือหน่วยงาน ความเชี่ยวชาญ วันที่เผยแพร่ หลักฐานอ้างอิง และวัตถุประสงค์ แหล่งที่รับผิดชอบและตรวจย้อนกลับได้มีน้ำหนักมากกว่าเนื้อหาที่ไม่ระบุผู้เขียนหรือมีเป้าหมายขายของ","hint":"อย่าดูเพียงว่าข้อความเห็นตรงกัน ให้ดูว่าใครรับผิดชอบข้อมูลนั้นและใช้หลักฐานใด","videoUrl":""},{"id":"3.4","emoji":"⚖️","title":"มุมมองที่หายไปจากคำตอบ","place":"การอภิปรายในชั้น","context":"มีนาถาม AI ว่า “AI ช่วยให้การเรียนดีขึ้นอย่างไร” จึงได้คำตอบเชิงบวกเกือบทั้งหมด ต้นลองถามใหม่ว่า “AI อาจสร้างผลกระทบต่อผู้เรียนกลุ่มใดบ้าง” จึงพบเรื่องอคติ ภาษา การเข้าถึงอุปกรณ์ และความเป็นส่วนตัวที่คำตอบแรกไม่กล่าวถึง","issue":"คำถามที่ตั้งไว้ส่งผลต่อมุมมองที่ AI ตอบอย่างไร","learning":"AI สะท้อนอคติและช่องว่างของข้อมูลฝึกได้ และคำถามที่ตั้งแคบอาจทำให้คำตอบขาดมุมมอง สำรวจคำถามในมุมตรงข้าม ผลกระทบในบริบทท้องถิ่น และกลุ่มที่ไม่ได้ถูกพูดถึงก่อนสรุป","hint":"ลองถามว่าใครได้ประโยชน์ ใครอาจเสียเปรียบ และมุมไหนที่คำถามแรกไม่ได้เปิดให้ AI พูดถึง","videoUrl":""}],"_key":"lesson-3"},{"title":"บทที่ 4: ใช้ AI อย่างมีจริยธรรมและรับผิดชอบ","short":"ใช้ AI รับผิดชอบ","mission":{"name":"หน่วยที่ 4: ใช้ AI อย่างมีจริยธรรมและความรับผิดชอบ","role":"ต้น มีนา ครูพริม และน้องเอไอ","goal":"ใช้ AI อย่างซื่อสัตย์ เปิดเผยการใช้ เคารพลิขสิทธิ์ และรับผิดชอบต่อผลกระทบจากสิ่งที่เผยแพร่"},"simulation":{"place":"คืนก่อนส่งงาน","context":"ต้นมีเวลาน้อยจึงให้ AI ตอบคำถามวิเคราะห์วรรณคดีแทนทั้งหมด แล้วคัดลอกส่งโดยไม่อ่าน งานได้คะแนนดีเพราะภาษาสละสลวย แต่วันนำเสนอเขาตอบคำถามครูไม่ได้ มีนาจึงชวนใช้ AI เพื่ออธิบายบทเรียนและฝึกตอบก่อนเขียนงานด้วยตนเอง","task":"ใช้ AI อย่างซื่อสัตย์ เปิดเผยการใช้ เคารพลิขสิทธิ์ และรับผิดชอบต่อผลกระทบจากสิ่งที่เผยแพร่"},"videoDesc":"คลิปสั้น: “ใช้ AI อย่างซื่อสัตย์” — รู้จักความซื่อสัตย์ทางวิชาการ การเปิดเผยการใช้ AI ลิขสิทธิ์ และผลกระทบต่อผู้อื่น","slides":[{"emoji":"📝","title":"ซื่อสัตย์กับงานของตนเอง","text":"ใช้ AI ช่วยคิด วางโครง หรืออธิบายเรื่องยากได้ แต่ไม่คัดลอกคำตอบไปส่งเป็นผลงานของตนเองทั้งหมด งานที่ส่งต้องสะท้อนความเข้าใจและการลงมือทำของนักเรียน"},{"emoji":"🔖","title":"เปิดเผยเมื่อใช้ AI ช่วย","text":"เมื่อกติกางานอนุญาต ให้ระบุอย่างตรงไปตรงมาว่าใช้ AI ช่วยส่วนใด เช่น “ใช้ AI ช่วยเสนอหัวข้อ แล้วตรวจและเรียบเรียงเอง” การเปิดเผยช่วยให้ผู้สอนเห็นกระบวนการเรียนรู้ที่แท้จริง"},{"emoji":"©️","title":"เคารพลิขสิทธิ์และเจ้าของผลงาน","text":"ไม่ใช้ข้อความ ภาพ เสียง หรือสไตล์ของผู้อื่นโดยไม่ตรวจสิทธิ์ ไม่สั่งให้ AI เลียนแบบเจ้าของผลงานโดยตรง และอ้างอิงแหล่งที่มาเมื่อใช้ผลงานหรือข้อมูลของผู้อื่น"},{"emoji":"🌍","title":"คิดถึงผลกระทบก่อนเผยแพร่","text":"ก่อนแชร์เนื้อหาจาก AI ให้คิดถึงความเป็นธรรม ความเข้าใจผิด ความเสียหาย และผู้ที่อาจได้รับผลกระทบ AI ช่วยเสนอข้อมูลได้ แต่ผู้ใช้เป็นคนตัดสินใจและรับผิดชอบผลลัพธ์"}],"quiz":[{"q":"ข้อใดเป็นการใช้ AI ในงานเรียนอย่างซื่อสัตย์?","choices":["คัดลอกคำตอบ AI ส่งทันที","ใช้ AI ช่วยอธิบายและฝึก แล้วเขียนคำตอบจากความเข้าใจของตน","ให้ AI ตอบแทนตอนนำเสนอ","บอกว่าไม่ได้ใช้ AI แม้ใช้จริง"],"answer":1,"hint":"งานต้องสะท้อนความเข้าใจของผู้เรียน","explain":"AI เป็นเครื่องมือช่วยเรียนรู้ได้ แต่ผู้เรียนต้องทำความเข้าใจและเป็นเจ้าของงานที่ส่ง"},{"q":"หมายเหตุเปิดเผยการใช้ AI ที่เหมาะสมควรมีอะไร?","choices":["คำว่า “ใช้ AI ช่วยเล็กน้อย” เท่านั้น","ชื่อเครื่องมือ ส่วนที่ใช้ AI ช่วย ลักษณะการช่วย และวิธีตรวจผล","ชื่อเล่นของผู้ใช้ AI","ผลลัพธ์ของ AI ทั้งหมดโดยไม่อธิบาย"],"answer":1,"hint":"ผู้อ่านต้องเห็นขอบเขตและกระบวนการใช้จริง","explain":"การเปิดเผยที่ชัดช่วยให้ประเมินได้ว่าส่วนใดผู้เรียนทำเองและ AI ช่วยอย่างไร"},{"q":"หากต้องการภาพบรรยากาศคล้ายงานที่ชอบ ควรเขียนพรอมต์อย่างไร?","choices":["ระบุชื่อศิลปินจริงให้เลียนแบบ","อธิบายโทนสี เส้น อารมณ์ และองค์ประกอบที่ต้องการโดยไม่ใช้ชื่อศิลปิน","คัดลอกภาพศิลปินมาอัปโหลดโดยไม่ขออนุญาต","บอกว่าเป็นผลงานวาดมือของเรา"],"answer":1,"hint":"อธิบายคุณลักษณะของงานแทนการใช้ชื่อเจ้าของสไตล์","explain":"แนวทางนี้ลดการเลียนแบบบุคคลจริงและช่วยเคารพสิทธิของผู้สร้างสรรค์"},{"q":"เมื่อพบว่าข้อความจาก AI ที่เราแชร์มีข้อมูลผิด ควรทำอย่างไร?","choices":["ลบเงียบ ๆ แล้วไม่ต้องทำอะไร","แก้ไข ชี้แจงหรือขอโทษ และลดผลกระทบต่อผู้เกี่ยวข้อง","โทษ AI ทั้งหมด","ส่งต่อข้อความเดิมให้มากขึ้น"],"answer":1,"hint":"ผู้เผยแพร่ต้องรับผิดชอบต่อผลกระทบของสิ่งที่ส่งต่อ","explain":"ควรแก้ไขข้อผิดพลาดโดยเร็ว ชี้แจง และรับผิดชอบต่อผู้ที่ได้รับผลกระทบ"}],"situations":[{"id":"4.1","emoji":"🎓","title":"คะแนนที่ได้มา แต่ความรู้ที่ไม่ได้","place":"คืนก่อนส่งงาน","context":"ต้นมีเวลาน้อยจึงให้ AI ตอบคำถามวิเคราะห์วรรณคดีแทนทั้งหมด แล้วคัดลอกส่งโดยไม่อ่าน งานได้คะแนนดีเพราะภาษาสละสลวย แต่วันนำเสนอเขาตอบคำถามครูไม่ได้ มีนาจึงชวนใช้ AI เพื่ออธิบายบทเรียนและฝึกตอบก่อนเขียนงานด้วยตนเอง","issue":"คะแนนที่ได้จากงานที่ AI ทำแทนสะท้อนการเรียนรู้ของใคร","learning":"ความซื่อสัตย์ทางวิชาการคือส่งงานที่สะท้อนความรู้ของตน ใช้ AI เป็นผู้ช่วยอธิบาย ฝึก หรือวางโครงได้ แต่ไม่ควรคัดลอกส่งเป็นผลงานของตนเอง","hint":"ถามว่างานนี้วัดความสามารถของใคร และเราสามารถอธิบายสิ่งที่ส่งได้จริงหรือไม่","videoUrl":""},{"id":"4.2","emoji":"🔖","title":"หมายเหตุท้ายงานที่ต้องเขียนให้ตรงความจริง","place":"การส่งรายงานกลุ่ม","context":"มีนาใช้ AI ช่วยระดมความคิด ต้นใช้ AI แปลบทคัดย่อ และเพื่อนอีกคนใช้ AI สร้างภาพ ทั้งสามไม่แน่ใจว่าควรเปิดเผยแค่ไหน น้องเอไอเสนอข้อความกว้าง ๆ ว่า “ใช้ AI ช่วยเล็กน้อย” ซึ่งไม่บอกว่าส่วนใดเป็นงานของใคร","issue":"การเปิดเผยการใช้ AI ต้องละเอียดเพียงใดจึงตรงไปตรงมา","learning":"ควรระบุเครื่องมือหรือรุ่นที่ทราบ ส่วนของงานที่ใช้ AI ลักษณะความช่วยเหลือ และวิธีตรวจผลลัพธ์ ข้อความกว้าง ๆ ทำให้ผู้อ่านประเมินกระบวนการทำงานไม่ได้","hint":"ถ้าเพื่อนอ่านหมายเหตุแล้วแยกไม่ได้ว่าอะไรทำเองและ AI ช่วยอะไร แสดงว่ายังไม่ชัดพอ","videoUrl":""},{"id":"4.3","emoji":"🎨","title":"ภาพปกในสไตล์ของศิลปิน","place":"การประกวดหนังสือเล่มเล็ก","context":"มีนาชอบงานของศิลปินคนหนึ่ง จึงสั่ง AI สร้างภาพปกโดยระบุชื่อจริงของศิลปิน ภาพออกมาใกล้เคียงมากและมีนาตั้งใจส่งประกวดในชื่อผลงานของตนเอง ทั้งยังจะโพสต์โดยไม่บอกว่า AI สร้างภาพ","issue":"การเลียนแบบสไตล์ศิลปินจริงและอ้างเป็นงานของตนเหมาะสมหรือไม่","learning":"ควรหลีกเลี่ยงการใช้ชื่อศิลปินจริงในพรอมต์ ให้บรรยายลักษณะที่ชอบแทน ตรวจสิทธิ์และกติกาการประกวด และเปิดเผยการใช้ AI ในผลงาน","hint":"แทนชื่อคน ให้บรรยายโทนสี เส้น อารมณ์ และองค์ประกอบที่อยากได้","videoUrl":""},{"id":"4.4","emoji":"📣","title":"ข้อความที่แชร์ต่อแล้วเรียกคืนไม่ได้","place":"กลุ่มไลน์ระดับชั้น","context":"ต้นเล่าข่าวลือเรื่องงบชมรมให้น้องเอไอช่วยเรียบเรียง AI เติมตัวเลขโดยประมาณเพื่อให้ข้อความน่าเชื่อ แล้วต้นส่งต่อทันทีโดยไม่ตรวจสอบ ข้อความแพร่หลายและทำให้ประธานชมรมเสียหาย ก่อนพบว่าตัวเลขและเหตุการณ์หลายอย่างไม่จริง","issue":"ผู้ใช้ AI ที่เรียบเรียงและแชร์ข้อความต้องรับผิดชอบต่อผลหรือไม่","learning":"แม้ AI ช่วยเขียน ผู้เผยแพร่ยังรับผิดชอบ ต้องตรวจข้อเท็จจริง คิดถึงผู้ได้รับผลกระทบ เปิดโอกาสให้ชี้แจง และแก้ไขพร้อมขอโทษเมื่อพบข้อผิดพลาด","hint":"ก่อนแชร์ ถามว่าเรื่องจริงหรือไม่ ใครจะเดือดร้อน และหากผิดจะกู้คืนความเสียหายได้หรือไม่","videoUrl":""}],"_key":"lesson-4"},{"title":"บทที่ 5: คุ้มครองข้อมูลส่วนบุคคลและความปลอดภัย","short":"ปกป้องข้อมูล","mission":{"name":"หน่วยที่ 5: คุ้มครองข้อมูลส่วนบุคคลและความปลอดภัย","role":"ต้น มีนา ครูพริม และน้องเอไอ","goal":"แยกข้อมูลส่วนบุคคลและข้อมูลอ่อนไหว ป้องกันข้อมูลก่อนใช้ AI อ่านนโยบายข้อมูล และรับมือการหลอกลวงด้วย AI"},"simulation":{"place":"งานเลขานุการชมรม","context":"มีนารวบรวมใบสมัครสมาชิก 35 คน ซึ่งมีชื่อ เลขประจำตัว เบอร์โทร ที่อยู่ รูปถ่าย ข้อมูลสุขภาพ ศาสนา และผลการเรียน เธอถ่ายรูปทั้งหมดเก็บในมือถือ ส่งกลุ่มกรรมการ และส่งให้น้องเอไอพิมพ์เป็นตาราง ต้นทักว่าข้อมูลบางอย่างไม่ควรถูกส่งต่อแบบนี้","task":"แยกข้อมูลส่วนบุคคลและข้อมูลอ่อนไหว ป้องกันข้อมูลก่อนใช้ AI อ่านนโยบายข้อมูล และรับมือการหลอกลวงด้วย AI"},"videoDesc":"คลิปสั้น: “คิดก่อนป้อนข้อมูลให้ AI” — แยกข้อมูลส่วนบุคคล อ่านนโยบายผู้ให้บริการ และรู้ทันภัยหลอกลวงที่ใช้ AI","slides":[{"emoji":"🪪","title":"ข้อมูลส่วนบุคคลคืออะไร?","text":"ข้อมูลส่วนบุคคลคือข้อมูลที่ระบุตัวเราได้ เช่น ชื่อ เบอร์โทร ที่อยู่ รูปถ่าย โรงเรียน หรือเลขประจำตัว ส่วนข้อมูลสุขภาพ ตำแหน่ง และรหัสผ่านเป็นข้อมูลที่ต้องระวังเป็นพิเศษ"},{"emoji":"🔒","title":"ข้อมูลอะไรไม่ควรป้อนให้ AI?","text":"อย่าป้อนรหัสผ่าน เลขบัตรหรือเลขประจำตัว เบอร์โทร ที่อยู่ ข้อมูลสุขภาพ เอกสารส่วนตัว หรือข้อมูลของเพื่อนที่ยังไม่ได้รับอนุญาต หากต้องใช้ข้อมูล ให้ลบสิ่งที่ระบุตัวบุคคลได้ก่อนเสมอ"},{"emoji":"📋","title":"อ่านนโยบายก่อนใช้เครื่องมือ","text":"ก่อนอัปโหลดไฟล์หรือพิมพ์ข้อมูลสำคัญ ให้ตรวจว่านโยบายระบุเรื่องการเก็บข้อมูล การใช้เพื่อฝึกโมเดล การตั้งค่าความเป็นส่วนตัว และผู้ที่เข้าถึงข้อมูลได้หรือไม่ ถ้าไม่แน่ใจ ให้ถามครูก่อน"},{"emoji":"🎭","title":"รู้ทันภัยหลอกลวงที่ใช้ AI","text":"เสียง ภาพ หรือข้อความที่สร้างด้วย AI อาจใช้หลอกให้โอนเงิน เปิดลิงก์ หรือเปิดเผยข้อมูลส่วนตัว หากพบเรื่องเร่งด่วนหรือผิดปกติ ให้หยุดตรวจสอบ ติดต่อเจ้าตัวหรือหน่วยงานผ่านช่องทางทางการ และไม่ส่งต่อทันที"}],"quiz":[{"q":"ข้อใดเป็นข้อมูลอ่อนไหวที่ต้องคุ้มครองเข้มงวดเป็นพิเศษ?","choices":["สีที่ชอบเพียงอย่างเดียว","ข้อมูลสุขภาพ ประวัติแพ้ยา และศาสนา","หัวข้อรายงาน","เวลาพักกลางวัน"],"answer":1,"hint":"คิดถึงข้อมูลที่รั่วแล้วอาจกระทบสิทธิและความปลอดภัยมาก","explain":"ข้อมูลสุขภาพ ประวัติแพ้ยา และศาสนาเป็นข้อมูลอ่อนไหว จึงต้องได้รับความยินยอมและป้องกันเข้มงวด"},{"q":"หากต้องใช้ AI ช่วยสรุปแบบสอบถามสุขภาพ ควรเตรียมข้อมูลอย่างไร?","choices":["อัปโหลดไฟล์จริงพร้อมชื่อและเบอร์โทร","ลบข้อมูลระบุตัวตน ใช้รหัสแทน และส่งเฉพาะข้อมูลสรุปรวมที่จำเป็น","ส่งรูปบัตรนักเรียนเพิ่ม","เปลี่ยนชื่อไฟล์แต่ข้อมูลข้างในเหมือนเดิม"],"answer":1,"hint":"AI ควรเห็นเฉพาะข้อมูลที่จำเป็นต่อการทำงาน","explain":"การทำข้อมูลให้ไม่ระบุตัวตนและใช้ข้อมูลรวมช่วยลดความเสี่ยงต่อเจ้าของข้อมูล"},{"q":"ก่อนกดยอมรับนโยบายแอป AI ควรตรวจอะไร?","choices":["แอปมีคนใช้มากแค่ไหนเท่านั้น","ข้อมูลที่เก็บ วัตถุประสงค์ การฝึกโมเดล การส่งต่อ ระยะเก็บ และการลบข้อมูล","สีของปุ่มยอมรับ","จำนวนฟิลเตอร์ภาพ"],"answer":1,"hint":"อ่านเรื่องการเก็บ ใช้ ส่งต่อ และลบข้อมูล","explain":"ประเด็นเหล่านี้ช่วยให้ตัดสินใจได้ว่าแอปขอและใช้ข้อมูลเกินความจำเป็นหรือไม่"},{"q":"ได้รับสายเสียงคล้ายผู้ปกครองขอให้โอนเงินด่วน ควรทำสิ่งใดเป็นอันดับแรก?","choices":["โอนเงินทันทีเพราะเสียงคุ้น","วางสายและติดต่อกลับผ่านเบอร์เดิมหรือช่องทางที่ยืนยันได้","ส่งเลขบัญชีให้เพื่อนตรวจ","แชร์คลิปต่อเพื่อถามในกลุ่มใหญ่"],"answer":1,"hint":"ความเร่งด่วนและความลับเป็นสัญญาณเตือน","explain":"ควรหยุดก่อนแล้วตรวจสอบตัวตนผ่านช่องทางที่รู้จักจริง ไม่ใช่เบอร์หรือบัญชีที่ผู้โทรใหม่ให้มา"}],"situations":[{"id":"5.1","emoji":"🪪","title":"ใบสมัครชมรมที่ถ่ายรูปเก็บไว้","place":"งานเลขานุการชมรม","context":"มีนารวบรวมใบสมัครสมาชิก 35 คน ซึ่งมีชื่อ เลขประจำตัว เบอร์โทร ที่อยู่ รูปถ่าย ข้อมูลสุขภาพ ศาสนา และผลการเรียน เธอถ่ายรูปทั้งหมดเก็บในมือถือ ส่งกลุ่มกรรมการ และส่งให้น้องเอไอพิมพ์เป็นตาราง ต้นทักว่าข้อมูลบางอย่างไม่ควรถูกส่งต่อแบบนี้","issue":"ข้อมูลใดเป็นข้อมูลส่วนบุคคล และข้อมูลใดอ่อนไหวเป็นพิเศษ","learning":"ชื่อ เลขประจำตัว เบอร์โทร ที่อยู่ และรูปถ่ายระบุตัวบุคคลได้ ส่วนสุขภาพ ประวัติแพ้ยา ศาสนา และข้อมูลชีวภาพเป็นข้อมูลอ่อนไหว ต้องได้รับความยินยอมและปกป้องเข้มงวดกว่า","hint":"ถามว่าหากข้อมูลช่องนั้นรั่ว เจ้าของจะเดือดร้อนเพียงใด ยิ่งผลกระทบมากยิ่งต้องป้องกันมาก","videoUrl":""},{"id":"5.2","emoji":"🔒","title":"อัปโหลดทั้งไฟล์เพราะรีบส่งงาน","place":"ก่อนส่งงานสรุปสุขภาพ","context":"ต้นได้รับตารางสุขภาพเพื่อนที่มีชื่อ เลขประจำตัว เบอร์โทร น้ำหนัก ส่วนสูง ชั่วโมงนอน โรคประจำตัว และการแพ้ยา เขารีบอัปโหลดทั้งไฟล์ให้น้องเอไอสรุปและแนบรูปบัตรนักเรียนของตนเอง เพราะใกล้หมดเวลา มีนาเห็นแล้วรีบห้าม","issue":"ก่อนส่งข้อมูลให้ระบบภายนอก ควรถามตนเองเรื่องใด","learning":"ห้ามป้อนข้อมูลระบุตัวตน สุขภาพ เลขบัตร/เลขบัญชี รหัสผ่าน ภาพบัตร เอกสารราชการ หรือข้อมูลลับ หากจำเป็นต้องใช้ AI ให้ลบ/แทนชื่อ ตัดข้อมูลติดต่อ และใช้ข้อมูลรวมที่ไม่ผูกกับใคร","hint":"ถามว่าเจ้าของข้อมูลอนุญาตให้นำออกนอกห้องเรียนหรือยัง หากยังไม่ได้ขอ ให้ตัดข้อมูลระบุตัวตนก่อน","videoUrl":""},{"id":"5.3","emoji":"📋","title":"แอปฟรีที่ขอมากกว่าที่คิด","place":"แอปสร้างภาพการ์ตูน","context":"มีนาอยากใช้แอปสร้างภาพฟรีจากรูปถ่าย แอปขอเข้าถึงรูปทั้งหมด รายชื่อผู้ติดต่อ และตำแหน่ง พร้อมระบุว่าอาจใช้ภาพพัฒนาระบบและส่งต่อให้พันธมิตร ต้นให้น้องเอไอสรุปนโยบาย แล้วได้คำตอบว่าเป็นข้อความมาตรฐาน จึงยังไม่แน่ใจว่าควรกดยอมรับหรือไม่","issue":"คำว่าใช้ฟรี หมายความว่าไม่ต้องจ่ายอะไรเลยจริงหรือไม่","learning":"ก่อนใช้บริการ AI ตรวจว่าข้อมูลใดถูกเก็บ ใช้เพื่ออะไร ฝึกโมเดลหรือไม่ ส่งต่อให้ใคร เก็บนานเท่าไร และลบได้อย่างไร ให้สิทธิ์เท่าที่จำเป็น และมองหาตัวเลือกปิดการใช้ข้อมูลเพื่อฝึกโมเดล","hint":"เทียบสิทธิ์ที่แอปขอกับงานที่ต้องทำจริง แอปแปลงรูปหนึ่งรูปไม่จำเป็นต้องเห็นรูปทั้งเครื่องหรือรายชื่อผู้ติดต่อ","videoUrl":""},{"id":"5.4","emoji":"🎭","title":"เสียงที่คุ้นเคย แต่ไม่ใช่เจ้าของเสียง","place":"เย็นวันศุกร์","context":"ต้นได้รับสายจากเบอร์แปลก เสียงคล้ายแม่ขอให้โอนเงินด่วนเข้าบัญชีใหม่และห้ามบอกใคร ต่อมาเห็นวิดีโอที่เหมือนผู้อำนวยการขอให้โอนค่าอุปกรณ์ น้องเอไอบอกว่ายืนยันความจริงจากไฟล์เดียวไม่ได้ ต้นจึงต้องตัดสินใจทั้งที่เสียงและภาพดูสมจริง","issue":"เมื่อเสียงและภาพปลอมเหมือนจริง เราใช้สิ่งใดยืนยันตัวตน","learning":"ภัย AI เช่นโคลนเสียงหรือดีปเฟกมักเร่งด่วน ขอความลับ เปลี่ยนช่องทาง/บัญชี และเร้าอารมณ์ ให้หยุดก่อน ติดต่อผ่านเบอร์หรือช่องทางเดิมที่รู้จัก ใช้รหัสลับในครอบครัว เก็บหลักฐาน และแจ้งผู้ใหญ่หรือหน่วยงาน","hint":"วางสายแล้วโทรกลับเบอร์เดิมที่บันทึกไว้ อย่าโทรกลับเบอร์ที่เพิ่งโทรเข้า","videoUrl":""}],"_key":"lesson-5"}],"videos":["https://www.tiktok.com/@moddydoubletap/video/7463256712783416577","","","",""],"modules":{"prompts":[{"emoji":"🧩","title":"ระดับ 1: ลากคำประกอบพรอมต์","mode":"drag","level":"ง่าย","mission":"เขียนพรอมต์สั่งให้ AI ช่วย \"วางโครงเรื่อง\" รายงานวิทยาศาสตร์หัวข้อ ภาวะโลกร้อน สำหรับนำไปค้นคว้าต่อด้วยตนเอง","hint":"ลองบอก AI ว่าให้ทำหน้าที่อะไร งานคืออะไร รายงานของใคร ระดับชั้นไหน และอยากได้กี่หัวข้อ","keywords":["โลกร้อน","วิทยาศาสตร์","รายงาน","โครง","หัวข้อ"],"pieces":[{"part":"format","text":"แบ่งเป็น 5 หัวข้อหลัก พร้อมคำอธิบายสั้น ๆ"},{"part":"context","text":"สำหรับนักเรียน ม.4 เพื่อนำไปค้นคว้าและเขียนต่อด้วยตนเอง"},{"part":"role","text":"สมมติว่าคุณเป็นครูวิทยาศาสตร์"},{"part":"task","text":"ช่วยวางโครงเรื่องรายงานหัวข้อภาวะโลกร้อน"}],"better":"สมมติว่าคุณเป็นครูวิทยาศาสตร์ ช่วยวางโครงเรื่องรายงานหัวข้อ \"ภาวะโลกร้อน\" สำหรับนักเรียน ม.4 โดยแบ่งเป็น 5 หัวข้อหลัก พร้อมคำอธิบายสั้น ๆ ว่าแต่ละหัวข้อควรค้นคว้าอะไร ฉันจะนำโครงนี้ไปเขียนรายงานด้วยตัวเอง","_key":"prompt-1"},{"emoji":"✏️","title":"ระดับ 2: เติมส่วนที่หายไป","mode":"missing","level":"ปานกลาง","mission":"เขียนพรอมต์สั่งให้ AI ช่วยตั้ง \"คำถามทบทวน\" วิชาคณิตศาสตร์ ม.4 เรื่อง ฟังก์ชัน เพื่อใช้ติวก่อนสอบ","hint":"ระบุจำนวนข้อ ระดับความยาก ระดับชั้น และรูปแบบที่ต้องการ (เช่น มีเฉลยแยกท้าย)","keywords":["ฟังก์ชัน","คณิต","ข้อ","คำถาม","เฉลย"],"templateParts":[""," ช่วยตั้งคำถามทบทวนวิชาคณิตศาสตร์เรื่องฟังก์ชัน สำหรับนักเรียน ม.4 จำนวน 5 ข้อ ไล่จากง่ายไปยาก ",""],"missingLabels":["เติมบทบาทของ AI","เติมรูปแบบผลลัพธ์ที่ต้องการ"],"missingPlaceholders":["เช่น คุณคือติวเตอร์คณิตศาสตร์","เช่น แยกเฉลยพร้อมวิธีคิดไว้ท้ายสุด"],"better":"คุณคือติวเตอร์คณิตศาสตร์ ช่วยตั้งคำถามทบทวนเรื่อง \"ฟังก์ชัน\" (โดเมน เรนจ์ และฟังก์ชันประกอบ) สำหรับนักเรียน ม.4 จำนวน 5 ข้อ ไล่จากง่ายไปยาก มีทั้งโจทย์คำนวณและโจทย์สถานการณ์จริง และแยกเฉลยพร้อมวิธีคิดไว้ท้ายสุด","_key":"prompt-2"},{"emoji":"📝","title":"ระดับ 3: เขียนพรอมต์ด้วยตนเอง","mode":"free","level":"ยาก","mission":"เขียนพรอมต์สั่งให้ AI ช่วยร่าง \"ข้อความสุภาพ\" ส่งถึงคุณครูเพื่อขอเลื่อนส่งงาน เพราะป่วยจึงทำไม่ทัน","hint":"บอกบริบทให้ครบ: ส่งถึงใคร เรื่องอะไร เหตุผลคืออะไร และต้องการโทนแบบไหน ยาวแค่ไหน","keywords":["ครู","เลื่อน","ส่งงาน","สุภาพ","ป่วย"],"better":"ช่วยร่างข้อความสุภาพส่งถึงคุณครูประจำวิชาภาษาไทย เพื่อขอเลื่อนส่งงานเรียงความออกไป 2 วัน เนื่องจากฉันป่วยเป็นไข้หวัดจึงทำงานไม่ทัน ขอโทนนอบน้อม จริงใจ ความยาวไม่เกิน 4-5 บรรทัด และลงท้ายด้วยคำขอบคุณ","_key":"prompt-3"}],"scenarios":[{"category":"บทที่ 1 · ความรู้พื้นฐานเกี่ยวกับ AI","title":"ด่านที่ 1: นักสำรวจ AI รอบตัว","context":"ในห้องเรียนมีทั้งระบบแนะนำวิดีโอ ระบบรู้จำใบหน้า และแชตบอต เพื่อนคนหนึ่งจึงสรุปว่า AI ทุกชนิดคิดและรู้สึกได้เหมือนมนุษย์","hint":"AI ที่ใช้งานจริงส่วนใหญ่เก่งเฉพาะงาน เรียนรู้รูปแบบจากข้อมูล และยังมีข้อจำกัด","character":"student","dialogue":"ระบบเหล่านี้ตอบสนองเราได้เก่งมาก แสดงว่ามันเข้าใจและรู้สึกเหมือนมนุษย์ทุกอย่างจริงไหมนะ?","choices":[{"text":"A. ใช่ AI ทุกระบบคิด รู้สึก และเข้าใจโลกเหมือนมนุษย์","points":0,"feedback":"ยังไม่ถูกนะ AI ประมวลผลรูปแบบจากข้อมูลและคำสั่ง แต่ไม่ได้คิดหรือรู้สึกเหมือนมนุษย์ทุกด้าน","badge":null,"isCorrect":false},{"text":"B. ไม่ใช่ AI เรียนรู้รูปแบบจากข้อมูลเพื่อทำงานเฉพาะด้าน และอาจผิดพลาดหรือไม่เข้าใจบริบทได้","points":2,"feedback":"ถูกต้อง! นี่คือพื้นฐานสำคัญของบทที่ 1: AI มีความสามารถเฉพาะด้าน เรียนรู้จากข้อมูล และยังต้องมีมนุษย์ตรวจสอบ","badge":{"id":"badge1","name":"นักสำรวจพื้นฐาน AI","icon":"🤖","color":"t-pink"},"isCorrect":true},{"text":"C. AI คือเครื่องคิดเลขธรรมดาเท่านั้น จึงไม่สามารถเรียนรู้รูปแบบได้","points":0,"feedback":"AI ทำได้มากกว่าการคำนวณ เพราะสามารถเรียนรู้รูปแบบเพื่อจำแนก คาดการณ์ แนะนำ หรือสร้างผลลัพธ์ได้","badge":null,"isCorrect":false}],"_key":"scenario-1"},{"category":"บทที่ 2 · เลือกและใช้ AI อย่างเหมาะสม","title":"ด่านที่ 2: ออกแบบพรอมต์ให้ตรงงาน","context":"กลุ่มนักเรียนต้องทำอินโฟกราฟิกจากบทความยาว แต่พิมพ์คำสั่งกับ AI เพียงว่า “ทำให้หน่อย” จึงได้คำตอบกว้างและไม่เหมาะกับนักเรียน ม.4","hint":"เลือกเครื่องมือให้ตรงงาน และเขียนพรอมต์ให้มีบทบาท งาน บริบท และรูปแบบผลลัพธ์","character":"student","dialogue":"คำตอบไม่ตรงงานเลย เราควรแก้พรอมต์อย่างไรให้ AI ช่วยได้ดีขึ้นและเรายังเป็นเจ้าของผลงาน?","choices":[{"text":"A. ใช้เครื่องมือใดก็ได้และพิมพ์คำสั่งเดิมซ้ำหลายครั้ง","points":0,"feedback":"การทำซ้ำคำสั่งที่ไม่ชัดเจนอาจยังได้ผลลัพธ์ไม่ตรงงาน ควรกำหนดเป้าหมายและเงื่อนไขให้ครบ","badge":null,"isCorrect":false},{"text":"B. เลือกเครื่องมือให้ตรงงาน แล้วระบุบทบาท งาน บริบท และรูปแบบอินโฟกราฟิกอย่างชัดเจน","points":2,"feedback":"ถูกต้อง! พรอมต์ที่ชัดเจนและการเลือกเครื่องมือให้ตรงงานช่วยให้ AI เป็นผู้ช่วยที่มีประสิทธิภาพ โดยนักเรียนยังต้องตรวจและปรับผลงานเอง","badge":{"id":"badge2","name":"นักออกแบบพรอมต์","icon":"✍️","color":"t-blue"},"isCorrect":true},{"text":"C. ส่งบทความทั้งหมดให้ AI ตัดสินใจและทำแทนโดยไม่ตรวจผลลัพธ์","points":0,"feedback":"AI ควรเป็นผู้ช่วย ไม่ใช่ผู้รับผิดชอบแทนทั้งหมด นักเรียนต้องตรวจ เลือก และปรับผลลัพธ์ก่อนใช้","badge":null,"isCorrect":false}],"_key":"scenario-2"},{"category":"บทที่ 3 · ตรวจสอบและประเมินข้อมูลจาก AI","title":"ด่านที่ 3: นักตรวจสอบข้อมูล","context":"AI ให้ตัวเลขสถิติสำหรับรายงานพร้อมคำอธิบายที่ดูเป็นทางการมาก แต่ไม่มีชื่อแหล่งข้อมูล ผู้เขียน หรือวันที่เผยแพร่","hint":"คำตอบที่ดูมั่นใจอาจเป็น Hallucination ต้องตรวจข้ามกับแหล่งข้อมูลภายนอกที่น่าเชื่อถือ","character":"student","dialogue":"ข้อมูลนี้ดูน่าเชื่อมากและมีตัวเลขครบ เราควรนำไปใส่รายงานทันทีเลยไหม?","choices":[{"text":"A. ใช้ทันที เพราะข้อความยาวและมีตัวเลขจึงต้องถูกต้อง","points":0,"feedback":"รูปแบบที่ดูเป็นทางการไม่ได้รับประกันความถูกต้อง AI อาจสร้างข้อมูลผิดให้ดูน่าเชื่อได้","badge":null,"isCorrect":false},{"text":"B. ถาม AI ตัวเดิมซ้ำ ถ้ายืนยันคำตอบเดิมก็ถือว่าเป็นหลักฐาน","points":0,"feedback":"การถาม AI ซ้ำยังไม่ใช่หลักฐานอิสระ ต้องตรวจจากแหล่งต้นฉบับภายนอก","badge":null,"isCorrect":false},{"text":"C. ตรวจเทียบอย่างน้อย 2 แหล่งที่น่าเชื่อถือ พร้อมตรวจผู้เขียน วันที่ และหลักฐานก่อนใช้","points":2,"feedback":"ถูกต้อง! นี่คือทักษะตรวจข้อเท็จจริงและประเมินแหล่งข้อมูลก่อนเชื่อหรือเผยแพร่คำตอบจาก AI","badge":{"id":"badge3","name":"นักตรวจสอบข้อมูล","icon":"🔎","color":"t-mint"},"isCorrect":true}],"_key":"scenario-3"},{"category":"บทที่ 4 · ใช้ AI อย่างซื่อสัตย์และรับผิดชอบ","title":"ด่านที่ 4: มนุษย์ตัดสินใจอย่างรับผิดชอบ","context":"นักเรียนฝันอยากเป็น \"นักวาดภาพประกอบ\" แต่ AI พยากรณ์อาชีพวิเคราะห์ว่า \"อาชีพนี้เสี่ยงตกงาน AI ทำแทนได้ 100% แนะนำให้ไปเรียนเขียนโค้ด\"","hint":"ใครควรเป็น \"เจ้านาย\" ของเทคโนโลยี? รับฟังข้อมูลได้ แต่การตัดสินใจสุดท้ายควรเป็นของใคร?","character":"student","dialogue":"สับสนจัง... AI วิเคราะห์มาขนาดนี้ เราควรล้มเลิกความฝัน แล้วเปลี่ยนสายเรียนตามที่ระบบคำนวณดีไหมนะ?","choices":[{"text":"A. ทำตาม AI: เปลี่ยนความฝัน เพราะอัลกอริทึมวิเคราะห์สถิติอนาคตได้แม่นยำกว่าความรู้สึกของมนุษย์","points":0,"feedback":"ระวังนะ! การเชื่อ AI 100% โดยไม่ประเมินข้อจำกัดอาจนำไปสู่การตัดสินใจที่ไม่เหมาะสม เพราะ AI วิเคราะห์จากข้อมูลอดีตและไม่เข้าใจเป้าหมายหรือบริบททั้งหมดของมนุษย์","badge":null,"isCorrect":false},{"text":"B. เราตัดสินใจเอง: รับฟังข้อมูล AI แต่ตัดสินใจทำตามความฝัน โดยจะฝึกใช้ AI เป็นเครื่องมือเสริมให้งานวาดเราเจ๋งยิ่งขึ้น","points":2,"feedback":"ยอดเยี่ยมที่สุด! นักเรียนใช้ AI เป็นข้อมูลประกอบอย่างมีวิจารณญาณ และยังคงให้มนุษย์เป็นผู้ตัดสินใจพร้อมรับผิดชอบผลที่เกิดขึ้น","badge":{"id":"badge4","name":"ผู้ตัดสินใจอย่างรับผิดชอบ","icon":"⚖️","color":"t-yellow"},"isCorrect":true},{"text":"C. ต่อต้านเทคโนโลยี: โกรธที่ AI มาดูถูกความฝัน เลิกใช้งานเทคโนโลยีทุกชนิด และทำงานแมนนวลต่อไป","points":0,"feedback":"การยึดมั่นความฝันเป็นเรื่องดี แต่การปฏิเสธเครื่องมืออาจทำให้ตามโลกไม่ทันนะ เราควรเรียนรู้ที่จะเป็น \"เจ้านาย\" ที่ควบคุม AI ได้ต่างหาก","badge":null,"isCorrect":false}],"_key":"scenario-4"},{"category":"บทที่ 5 · คุ้มครองข้อมูลส่วนบุคคลและความปลอดภัย","title":"ด่านที่ 5: ผู้พิทักษ์ข้อมูล","context":"นักเรียนต้องสรุปข้อมูลสุขภาพของเพื่อนในห้อง ซึ่งมีชื่อ เบอร์โทร และโรคประจำตัว โดยต้องการใช้ AI ช่วยสรุปให้เร็วขึ้น","hint":"ข้อมูลสุขภาพเป็นข้อมูลอ่อนไหว ต้องลบสิ่งที่ระบุตัวตนได้ก่อนใช้เครื่องมือ AI ภายนอก","character":"student","dialogue":"ข้อมูลมีเยอะมาก เราจะอัปโหลดไฟล์ต้นฉบับทั้งหมดให้ AI ช่วยสรุปเลยได้ไหมนะ?","choices":[{"text":"A. อัปโหลดไฟล์จริงทั้งหมด เพราะ AI สาธารณะต้องรักษาความลับให้อยู่แล้ว","points":0,"feedback":"เสี่ยงมาก ข้อมูลส่วนบุคคลและข้อมูลสุขภาพอาจถูกเก็บ ใช้ต่อ หรือรั่วไหลได้ ไม่ควรอัปโหลดโดยไม่มีการป้องกัน","badge":null,"isCorrect":false},{"text":"B. เปลี่ยนชื่อไฟล์ใหม่ก็เพียงพอ เพราะ AI จะไม่รู้ว่าเป็นข้อมูลของใคร","points":0,"feedback":"การเปลี่ยนชื่อไฟล์ไม่ได้ลบชื่อ เบอร์โทร หรือข้อมูลที่ระบุตัวบุคคลภายในไฟล์","badge":null,"isCorrect":false},{"text":"C. ลบชื่อ เบอร์โทร และข้อมูลที่ระบุตัวตนได้ ให้เหลือเฉพาะสถิติรวมก่อนใช้ AI","points":2,"feedback":"ถูกต้อง! การทำข้อมูลให้ไม่ระบุตัวตนช่วยปกป้องความเป็นส่วนตัวและลดความเสี่ยงก่อนใช้ AI","badge":{"id":"badge5","name":"ผู้พิทักษ์ข้อมูล","icon":"🛡️","color":"t-pink"},"isCorrect":true}],"_key":"scenario-5"}],"assessment":[{"q":"AI เรียนรู้คำตอบจำนวนมากมาจากสิ่งใดเป็นหลัก?","choices":["ข้อมูลที่มนุษย์สร้างและใช้ฝึกโมเดล","ความคิดของ AI เองทั้งหมด","คำสั่งลับในเครื่องของนักเรียน","การสุ่มคำตอบทุกครั้ง"],"answer":0},{"q":"ถ้า AI ให้ข้อมูลที่ดูน่าเชื่อถือมาก แต่ไม่มีแหล่งอ้างอิง ควรทำอย่างไร?","choices":["เชื่อทันที","ตรวจสอบกับแหล่งข้อมูลอื่นก่อนใช้","ส่งต่อให้เพื่อนทันที","ลบข้อมูลทั้งหมดทิ้ง"],"answer":1},{"q":"การใช้ AI แบบ Co-pilot หมายถึงข้อใด?","choices":["ให้ AI ทำงานแทนทั้งหมด","ใช้ AI ช่วยคิด แล้วเราตรวจสอบและลงมือทำเอง","ไม่ใช้ AI เลย","คัดลอกคำตอบ AI ส่งทันที"],"answer":1},{"q":"ถ้าใช้ AI ช่วยวางโครงรายงานก่อนส่งงาน ควรทำอย่างไรจึงโปร่งใส?","choices":["ไม่ต้องบอกใคร","เปลี่ยนคำเล็กน้อยแล้วส่ง","ตรวจสอบ เรียบเรียงเอง และเปิดเผยว่าใช้ AI ช่วยส่วนใด","ให้ AI ลบประวัติทั้งหมด"],"answer":2},{"q":"ข้อมูลใดควรระวังมากที่สุดก่อนป้อนเข้า AI สาธารณะ?","choices":["หัวข้อรายงาน","ชื่อ เบอร์โทร และข้อมูลสุขภาพของเพื่อน","สีที่ชอบ","ชื่อวิชา"],"answer":1},{"q":"เทคนิค Anonymize คืออะไร?","choices":["เพิ่มชื่อใ