patches jsonb := $patch$[{"videoUrl":"https://dearchotirat40.github.io/aware-ai-guardian-academy/public/scenario-1-1.mp4","contentRevision":4},{"context":"ต้นพิมพ์ถามน้องเอไอว่า “แนะนำหัวข้อโครงงานวิทยาศาสตร์ ม.4” แล้วกดปุ่มถามซ้ำอีกสองครั้งโดยไม่แก้ข้อความเลย ปรากฏว่าทั้งสามครั้งได้หัวข้อไม่เหมือนกัน มีซ้ำกันแค่บางหัวข้อ ต้นจึงสรุปว่า “มันสุ่มจากลิสต์ เหมือนจับฉลากนั่นแหละ” มีนายังไม่ปักใจเชื่อ จึงลองทดสอบแบบที่ง่ายกว่า เธอพิมพ์ประโยคที่ยังไม่จบว่า “วันนี้อากาศร้อน ฉันจึงอยาก” แล้วให้น้องเอไอเติมคำต่อท้าย 5 ครั้ง ได้คำว่า ดื่ม ว่าย นอน กิน และอาบ ทั้งห้าคำไม่ซ้ำกัน แต่ทุกคำเข้ากับประโยคได้อย่างสมเหตุสมผล ส่วนคำที่ขัดกับอากาศร้อนอย่าง ใส่เสื้อกันหนาว ไม่โผล่มาเลยสักครั้ง ครูพริมเห็นผลการทดลอง จึงชวนทั้งคู่คิดว่า ผลแบบนี้บอกอะไรเกี่ยวกับวิธีที่น้องเอไอเลือกคำ","learning":"โมเดลภาษาไม่ได้ประมวลผลทีละคำเต็ม ๆ แต่ตัดข้อความออกเป็นหน่วยย่อยเรียกว่า token ซึ่งอาจเป็นเพียงส่วนหนึ่งของคำ ภาษาไทยมักถูกตัดเป็นจำนวน token ต่อประโยคมากกว่าภาษาอังกฤษ เพราะไม่มีช่องว่างระหว่างคำ","imageUrl":"https://dearchotirat40.github.io/aware-ai-guardian-academy/public/scenario-1-2.png","imageAlt":"สถานการณ์ที่ 1.2 ถามเหมือนเดิม แต่ตอบไม่เหมือนเดิม: ต้นถามซ้ำ 3 ครั้ง มีนาทดลองเติมคำ 5 ครั้ง และครูพริมชวนคิด","activity":"ทดลองถามข้อความเดิม 3 ครั้ง แล้วเติมประโยค “วันนี้อากาศร้อน ฉันจึงอยาก” 5 ครั้ง สังเกตคำตอบที่ได้","videoUrl":"","contentRevision":2,"activityData":{"prompt":"แนะนำหัวข้อโครงงานวิทยาศาสตร์ ม.4","sentence":"วันนี้อากาศร้อน ฉันจึงอยาก","outputs":["การศึกษาการเจริญเติบโตของพืช · การลดขยะพลาสติกในโรงเรียน · ผลของแสงต่อการสังเคราะห์แสง · การสำรวจคุณภาพน้ำในชุมชน · การใช้พลังงานทดแทนในโรงเรียน","การศึกษาการเจริญเติบโตของพืช · สมบัติการดูดซับของถ่านกัมมันต์ · การพัฒนาผลิตภัณฑ์จากวัสดุเหลือใช้ · การตรวจวัดคุณภาพอากาศ · ผลของอุณหภูมิต่อการงอกของเมล็ด","การเพาะเลี้ยงจุลินทรีย์ในอาหาร · การลดขยะพลาสติกในโรงเรียน · การพัฒนาพลังงานจากกากพืช · การตรวจวัดคุณภาพน้ำในชุมชน · การใช้สมุนไพรในการยับยั้งเชื้อแบคทีเรีย"],"words":["ดื่ม","ว่าย","นอน","กิน","อาบ"],"note":"คำตัวอย่างชุดนี้ออกแบบสำหรับบริบทอากาศร้อน ลองสังเกตว่าคำเข้ากับประโยคที่คุณพิมพ์หรือไม่"}},{"context":"วิชาสังคมศึกษาสั่งรายงานค่าฝุ่น PM2.5 เขตสายไหม “ของสัปดาห์ที่ผ่านมา” กำหนดส่งวันศุกร์ มีนาพิมพ์คำค้นในเครื่องมือค้นหา แล้วอ่านกล่องสรุปคำตอบที่ AI เขียนไว้บนสุดของหน้า ได้ค่าเฉลี่ยราว 40 ไมโครกรัมต่อลูกบาศก์เมตร เธอคัดลอกตัวเลขนั้นลงรายงานทันทีโดยไม่ได้กดลิงก์ใด ส่วนต้นเลื่อนผ่านกล่องสรุปลงไปกดลิงก์ต้นทางที่อ้างไว้ใต้กล่อง พบว่าหน้านั้นเป็นข้อมูลของปี 2566 ไม่ใช่สัปดาห์ที่ผ่านมา เขาจึงเข้าเว็บหน่วยงานโดยตรงและพบตารางรายวันพร้อมชื่อสถานีตรวจวัดและวันที่เผยแพร่ เมื่อเฉลี่ยเจ็ดวันได้ 52 ไมโครกรัมต่อลูกบาศก์เมตร เหลือเวลาอีกสองวัน ทั้งคู่ต้องตัดสินใจว่าจะใช้ตัวเลขใด","mediaType":"chat","contentRevision":1,"videoUrl":"","storyScenes":[{"speaker":"ครูพริม","text":"รายงานสังคมศึกษาครั้งนี้ หาค่า PM2.5 เขตสายไหมของสัปดาห์ที่ผ่านมา ส่งวันศุกร์นะ","emoji":"🧑‍🏫"},{"speaker":"มีนา","text":"เราค้นแล้ว! กล่องสรุป AI บนสุดบอกเฉลี่ยประมาณ 40 ไมโครกรัมต่อลูกบาศก์เมตร","emoji":"👧"},{"speaker":"มีนา","text":"คัดลอก 40 ลงรายงานแล้ว ยังไม่ได้กดลิงก์ไหนเลย","emoji":"👧"},{"speaker":"ต้น","text":"เดี๋ยวก่อน เรากดลิงก์ต้นทางใต้กล่องแล้ว ข้อมูลเป็นปี 2566 ไม่ใช่สัปดาห์ที่ผ่านมา","emoji":"👦"},{"speaker":"มีนา","text":"อ้าว แล้วข้อมูลของสัปดาห์ที่ผ่านมาดูตรงไหน?","emoji":"👧"},{"speaker":"ต้น","text":"เราเข้าเว็บหน่วยงานโดยตรง มีตารางรายวัน ชื่อสถานีตรวจวัด และวันที่เผยแพร่ครบ","emoji":"👦"},{"speaker":"ต้น","text":"พอเฉลี่ยข้อมูลทั้ง 7 วัน ได้ 52 ไมโครกรัมต่อลูกบาศก์เมตร","emoji":"👦"},{"speaker":"มีนา","text":"เหลืออีกสองวันก่อนส่งวันศุกร์ เราจะใช้ 40 หรือ 52 แล้วควรตรวจอะไรอีก?","emoji":"👧"}]}]$patch$;
begin
 select data into old from public.app_curriculum where id='current' and updated_at=1789710660227 for update;
 if old is null then raise exception 'Curriculum changed; read latest version before retrying'; end if;
 insert into public.teacher_audit(actor,action,before_data) values(auth.uid(),'curriculum_media_chat_sync_20260918',jsonb_build_object('curriculum',old));
 result := seed || old;
 result := jsonb_set(result,'{modules}',(seed->'modules') || coalesce(old->'modules','{}'::jsonb));
 for i in 0..2 loop
  scene := (result#>array['lessons','0','situations',i::text]) || (patches->i);
  result := jsonb_set(result,array['lessons','0','situations',i::text],scene);
 end loop;
 stamp := (extract(epoch from clock_timestamp())*1000)::bigint;
 update public.app_curriculum set data=result,updated_at=stamp where id='current';
end $sync$;
commit;
select jsonb_array_length(data->'lessons') as bases, (select count(*) from jsonb_object_keys(data->'modules')) as editable_modules,
 data#>>'{lessons,0,situations,0,videoUrl}' as video,
 data#>>'{lessons,0,situations,1,imageUrl}' as image,
 data#>>'{lessons,0,situations,2,mediaType}' as chat,
 jsonb_array_length(data#>'{lessons,0,situations,2,storyScenes}') as chat_messages,
 updated_at from public.app_curriculum where id='current';